// Glossary of key terms for the pop-up definitions in the Learn notes (js/core/glossary.js). Original definitions in
// 9610 wording. Each entry: { t: term, a: [aliases], d: definition, r: subsection where the term is taught }.
window.BIO = window.BIO || {};
window.BIO.glossary = { status: "reviewed", entries: [
  // 3.1.1.1 Monomers and polymers
  { t: "monomer", a: [], d: "A smaller unit that can be joined to other similar units to form a polymer, e.g. α-glucose, amino acids and nucleotides.", r: "3.1.1.1" },
  { t: "polymer", a: [], d: "A large molecule made of many monomers joined by condensation reactions, e.g. starch, cellulose, polypeptides and DNA.", r: "3.1.1.1" },
  { t: "condensation", a: ["condensation reaction"], d: "A reaction that joins two molecules with a chemical bond and eliminates a molecule of water.", r: "3.1.1.1" },
  { t: "hydrolysis", a: ["hydrolyse", "hydrolysed", "hydrolysing", "hydrolysis reaction"], d: "A reaction that breaks the chemical bond between two molecules and uses a molecule of water.", r: "3.1.1.1" },
  { t: "covalent bond", a: [], d: "A strong chemical bond in which two atoms share a pair of electrons. Glycosidic, ester, peptide and phosphodiester bonds and disulfide bridges are all covalent.", r: "3.1.1.1" },

  // 3.1.1.2 Carbohydrates
  { t: "monosaccharide", a: [], d: "A single sugar unit; the monomer from which larger carbohydrates are made, e.g. glucose and fructose.", r: "3.1.1.2" },
  { t: "α-glucose", a: ["alpha-glucose", "alpha glucose"], d: "The isomer of glucose with the OH group on carbon 1 below the ring; the monomer of starch (and glycogen in animals), two of which form maltose; part of sucrose.", r: "3.1.1.2" },
  { t: "β-glucose", a: ["beta-glucose", "beta glucose"], d: "The isomer of glucose with the OH group on carbon 1 above the ring; the monomer of cellulose.", r: "3.1.1.2" },
  { t: "isomer", a: [], d: "One of two or more molecules with the same molecular formula but a different arrangement of atoms, e.g. α-glucose and β-glucose.", r: "3.1.1.2" },
  { t: "fructose", a: [], d: "A monosaccharide with the same formula as glucose but a different structure; joined to α-glucose it forms sucrose.", r: "3.1.1.2" },
  { t: "disaccharide", a: [], d: "A sugar formed by the condensation of two monosaccharides, joined by a glycosidic bond, e.g. maltose and sucrose.", r: "3.1.1.2" },
  { t: "glycosidic bond", a: ["glycosidic link", "glycosidic linkage"], d: "The covalent bond formed by condensation between two monosaccharides; it is broken by hydrolysis.", r: "3.1.1.2" },
  { t: "maltose", a: [], d: "A disaccharide formed by the condensation of two α-glucose molecules (an α-1,4 glycosidic bond); the product of starch digestion by amylase.", r: "3.1.1.2" },
  { t: "sucrose", a: [], d: "A non-reducing disaccharide formed by the condensation of α-glucose and fructose; the main sugar transported in the phloem.", r: "3.1.1.2" },
  { t: "lactose", a: [], d: "The disaccharide in milk, made of glucose and galactose; it is hydrolysed by lactase.", r: "3.2.2.2" },
  { t: "galactose", a: [], d: "A monosaccharide that, with glucose, makes up lactose; released when lactase hydrolyses lactose.", r: "3.2.2.2" },
  { t: "glycogen", a: [], d: "The highly branched storage polysaccharide of animals and fungi, made of α-glucose; its many ends allow rapid hydrolysis to glucose. Not named in the 9610 specification.", r: "3.1.1.2" },
  { t: "polysaccharide", a: [], d: "A carbohydrate polymer formed by the condensation of many monosaccharides, e.g. starch and cellulose.", r: "3.1.1.2" },
  { t: "starch", a: [], d: "The storage polysaccharide of plants, formed by the condensation of α-glucose and made of amylose and amylopectin; insoluble and compact, so it stores much glucose with no osmotic effect.", r: "3.1.1.2" },
  { t: "amylose", a: [], d: "The unbranched, helical component of starch: α-glucose joined by α-1,4 glycosidic bonds, coiled compactly for storage.", r: "3.1.1.2" },
  { t: "amylopectin", a: [], d: "The branched component of starch: α-glucose chains with α-1,4 glycosidic bonds and α-1,6 bonds at the branches, giving many ends for rapid hydrolysis.", r: "3.1.1.2" },
  { t: "cellulose", a: [], d: "A structural polysaccharide of β-glucose. Its straight, unbranched chains lie parallel and are linked by many hydrogen bonds into microfibrils, giving plant cell walls strength.", r: "3.1.1.2" },
  { t: "microfibril", a: [], d: "A bundle of parallel cellulose chains held together by many hydrogen bonds; microfibrils give plant cell walls high tensile strength.", r: "3.1.1.2" },
  { t: "reducing sugar", a: [], d: "A sugar that reduces the copper(II) ions in Benedict's reagent, giving a coloured precipitate on heating; all monosaccharides and some disaccharides, such as maltose.", r: "3.1.1.2" },
  { t: "non-reducing sugar", a: [], d: "A sugar, such as sucrose, that gives a negative Benedict's test until it is hydrolysed (by heating with dilute acid, then neutralising) into reducing monosaccharides.", r: "3.1.1.2" },
  { t: "Benedict's test", a: ["Benedict’s test", "Benedict's reagent", "Benedict’s reagent", "Benedict's solution", "Benedict’s solution", "Benedict's", "Benedict’s"], d: "Test for reducing sugars: heat the sample with blue Benedict's reagent; a green, yellow, orange or brick-red precipitate shows a reducing sugar, depending on its concentration.", r: "3.1.1.2" },
  { t: "iodine test", a: ["iodine solution", "iodine in potassium iodide", "iodine/potassium iodide", "iodine"], d: "Test for starch: add iodine in potassium iodide solution; it changes from orange-brown to blue-black if starch is present.", r: "3.1.1.2" },

  // 3.1.1.3 Lipids
  { t: "triglyceride", a: [], d: "A lipid formed by the condensation of one glycerol molecule and three fatty acids, making three ester bonds; an energy store.", r: "3.1.1.3" },
  { t: "glycerol", a: [], d: "A three-carbon molecule with three OH groups that condenses with fatty acids to form triglycerides and phospholipids.", r: "3.1.1.3" },
  { t: "fatty acid", a: [], d: "A molecule with a carboxyl group joined to a hydrocarbon chain, written RCOOH; the R group may be saturated or unsaturated.", r: "3.1.1.3" },
  { t: "ester bond", a: [], d: "The covalent bond formed by condensation between an OH group of glycerol and the carboxyl group of a fatty acid.", r: "3.1.1.3" },
  { t: "saturated fatty acid", a: ["saturated fat", "saturated triglyceride"], d: "A fatty acid whose hydrocarbon chain has only single carbon-carbon bonds, so it carries the maximum number of hydrogen atoms and is straight. Fats rich in them are usually solid at room temperature.", r: "3.1.1.3" },
  { t: "unsaturated fatty acid", a: ["unsaturated fat", "unsaturated triglyceride"], d: "A fatty acid with one or more carbon-carbon double bonds (C=C) in its chain, which put kinks in it. Fats rich in them are usually liquid oils at room temperature.", r: "3.1.1.3" },
  { t: "phospholipid", a: [], d: "A lipid in which one of the three fatty acids of a triglyceride is replaced by a phosphate-containing group, giving a hydrophilic head and two hydrophobic tails.", r: "3.1.1.3" },
  { t: "hydrophilic", a: [], d: "Attracted to water. Polar or charged groups are hydrophilic because they interact with water molecules, e.g. the phosphate head of a phospholipid.", r: "3.1.1.3" },
  { t: "hydrophobic", a: [], d: "Not attracted to water. Non-polar groups, such as the hydrocarbon tails of fatty acids, are hydrophobic because they cannot form hydrogen bonds with water, so they cluster together away from it.", r: "3.1.1.3" },
  { t: "non-polar", a: ["nonpolar"], d: "Having no uneven spread of charge (no slightly positive and slightly negative regions), so not attracted to water. Small non-polar molecules, such as oxygen and carbon dioxide, pass easily through the phospholipid bilayer.", r: "3.1.1.3" },
  { t: "emulsion test", a: [], d: "Test for lipids: shake the sample with ethanol, then pour into water; a cloudy white emulsion shows that lipid is present.", r: "3.1.1.3" },

  // 3.1.1.4 Proteins
  { t: "amino acid", a: ["amino-acid"], d: "The monomer of proteins: a central carbon atom joined to an amino group (NH₂), a carboxyl group (COOH), a hydrogen atom and a variable R group.", r: "3.1.1.4" },
  { t: "amino group", a: [], d: "The NH₂ group of an amino acid; it forms part of a peptide bond.", r: "3.1.1.4" },
  { t: "carboxyl group", a: [], d: "The COOH group found in amino acids and fatty acids; it forms part of peptide bonds and ester bonds.", r: "3.1.1.4" },
  { t: "R group", a: ["R-group"], d: "The variable group joined to the central carbon of an amino acid. The twenty amino acids common to all organisms differ only in their R groups.", r: "3.1.1.4" },
  { t: "peptide bond", a: [], d: "The covalent bond formed by condensation between the carboxyl group of one amino acid and the amino group of another.", r: "3.1.1.4" },
  { t: "dipeptide", a: [], d: "Two amino acids joined by one peptide bond, formed by condensation.", r: "3.1.1.4" },
  { t: "polypeptide", a: [], d: "A chain of many amino acids joined by peptide bonds, formed by condensation. A protein is made of one or more polypeptides.", r: "3.1.1.4" },
  { t: "primary structure", a: ["amino acid sequence", "amino-acid sequence"], d: "The sequence (number and order) of amino acids in a polypeptide, held by peptide bonds. It determines how the polypeptide folds and so the protein's shape and function.", r: "3.1.1.4" },
  { t: "secondary structure", a: [], d: "The coiling of a polypeptide into an α-helix or its folding into a β-pleated sheet, held by hydrogen bonds between the C=O and N-H groups of the backbone.", r: "3.1.1.4" },
  { t: "tertiary structure", a: [], d: "The overall three-dimensional shape of a folded polypeptide, held by hydrogen bonds, ionic bonds and disulfide bridges between R groups, and hydrophobic interactions.", r: "3.1.1.4" },
  { t: "quaternary structure", a: [], d: "Two or more polypeptide chains, sometimes with non-protein groups such as haem, held together in one functional protein, e.g. haemoglobin and antibodies.", r: "3.1.1.4" },
  { t: "α-helix", a: ["alpha helix", "alpha-helix", "α helix", "α-helices"], d: "A type of secondary structure in which the polypeptide coils into a spiral held by hydrogen bonds.", r: "3.1.1.4" },
  { t: "β-pleated sheet", a: ["beta pleated sheet", "beta-pleated sheet", "β pleated sheet"], d: "A type of secondary structure in which parts of the polypeptide lie side by side in a folded sheet held by hydrogen bonds.", r: "3.1.1.4" },
  { t: "hydrogen bond", a: [], d: "A weak attraction between a slightly positive hydrogen atom and a slightly negative atom such as oxygen or nitrogen. Each is weak, but large numbers together are strong.", r: "3.1.1.4" },
  { t: "ionic bond", a: [], d: "An attraction between oppositely charged groups, e.g. between charged R groups in a protein; easily broken by changes in pH.", r: "3.1.1.4" },
  { t: "disulfide bridge", a: ["disulphide bridge", "disulfide bond", "disulphide bond"], d: "A strong covalent bond between the sulfur atoms of two cysteine R groups; it helps hold the tertiary and quaternary structure of proteins.", r: "3.1.1.4" },
  { t: "hydrophobic interaction", a: [], d: "The clustering of hydrophobic R groups together inside a folded protein, away from water; helps hold tertiary structure.", r: "3.1.1.4" },
  { t: "globular protein", a: [], d: "A protein folded into a compact, roughly spherical shape with a specific tertiary structure, usually soluble, e.g. enzymes, antibodies and haemoglobin.", r: "3.1.1.4" },
  { t: "biuret test", a: ["biuret reagent", "biuret"], d: "Test for proteins: add sodium hydroxide solution, then dilute copper(II) sulfate solution; a lilac or purple colour shows peptide bonds. No heating is needed.", r: "3.1.1.4" },

  // 3.1.2.1 Eukaryotic cells
  { t: "optical microscope", a: ["light microscope"], d: "A microscope that uses visible light focused by glass lenses. It can show living and coloured specimens, but its resolution is limited to about 0.2 µm by the wavelength of light.", r: "3.1.2.1" },
  { t: "electron microscope", a: [], d: "A microscope that uses a beam of electrons focused by electromagnets. The short wavelength of electrons gives much higher resolution, but specimens must be dead and in a vacuum.", r: "3.1.2.1" },
  { t: "transmission electron microscope", a: ["TEM"], d: "An electron microscope in which electrons pass through a very thin section, giving a two-dimensional image of internal ultrastructure at the highest resolution.", r: "3.1.2.1" },
  { t: "scanning electron microscope", a: ["SEM"], d: "An electron microscope in which a beam of electrons is scanned across the surface of a specimen, giving a three-dimensional image of the surface at lower resolution than a TEM.", r: "3.1.2.1" },
  { t: "magnification", a: [], d: "How many times larger the image is than the real object: magnification = size of image ÷ size of real object.", r: "3.1.2.1" },
  { t: "resolution", a: ["resolving power"], d: "The minimum distance between two points at which they can still be seen as separate. It is limited by the wavelength of the radiation used.", r: "3.1.2.1" },
  { t: "artefact", a: ["artifact"], d: "A feature in a micrograph that was produced by preparing the specimen (e.g. by dehydrating, staining or sectioning it) and is not present in the living cell.", r: "3.1.2.1" },
  { t: "micrograph", a: ["photomicrograph", "electron micrograph"], d: "A photograph of an image seen through a microscope.", r: "3.1.2.1" },
  { t: "ultrastructure", a: [], d: "The detailed structure of a cell and its organelles, seen only with an electron microscope.", r: "3.1.2.1" },
  { t: "cell fractionation", a: [], d: "Breaking cells open and separating their organelles: homogenisation in a cold, isotonic, buffered solution, filtration, then ultracentrifugation.", r: "3.1.2.1" },
  { t: "homogenisation", a: ["homogenise", "homogenised", "homogenising"], d: "Breaking up cells, e.g. in a blender, to release the organelles, in a solution that is cold (slows enzymes), isotonic (prevents osmotic damage) and buffered (keeps pH constant).", r: "3.1.2.1" },
  { t: "homogenate", a: [], d: "The mixture of broken cells and released organelles produced by homogenisation.", r: "3.1.2.1" },
  { t: "ultracentrifugation", a: ["differential centrifugation"], d: "Spinning a filtered homogenate at increasing speeds: the largest, densest organelles form a pellet first (nuclei, then mitochondria), and each supernatant is spun again, faster and for longer.", r: "3.1.2.1" },
  { t: "pellet", a: [], d: "The sediment at the bottom of a centrifuge tube, containing the components that settle out at that speed.", r: "3.1.2.1" },
  { t: "supernatant", a: [], d: "The liquid above the pellet after centrifugation, containing lighter components; it is poured off and spun again at a higher speed.", r: "3.1.2.1" },
  { t: "organelle", a: [], d: "A structure within a cell that has a particular function, e.g. a nucleus, mitochondrion or ribosome.", r: "3.1.2.1" },
  { t: "eukaryotic cell", a: ["eukaryote", "eukaryotic"], d: "A cell with a nucleus and membrane-bound organelles, such as the cells of animals, plants and fungi.", r: "3.1.2.1" },
  { t: "plasma membrane", a: [], d: "Any membrane with the fluid-mosaic structure in a cell: the cell-surface membrane and the membranes around and within organelles.", r: "3.1.2.1" },
  { t: "cell-surface membrane", a: ["cell surface membrane"], d: "The plasma membrane around a cell, which controls what enters and leaves it.", r: "3.1.2.1" },
  { t: "nucleus", a: ["nuclei"], d: "An organelle bounded by a nuclear envelope with pores, containing the cell's DNA as chromatin and one or more nucleoli; it controls the cell's activities.", r: "3.1.2.1" },
  { t: "nuclear envelope", a: [], d: "The double membrane around the nucleus, with nuclear pores; its outer membrane is continuous with the rough endoplasmic reticulum.", r: "3.1.2.1" },
  { t: "nuclear pore", a: [], d: "A gap in the nuclear envelope through which large molecules, such as mRNA, leave the nucleus.", r: "3.1.2.1" },
  { t: "nucleolus", a: ["nucleoli"], d: "A dense region inside the nucleus that makes ribosomal RNA and assembles ribosomes.", r: "3.1.2.1" },
  { t: "mitochondrion", a: ["mitochondria"], d: "An organelle with a double membrane whose inner membrane is folded into cristae; the site of the later stages of aerobic respiration, which produce most of the cell's ATP (glycolysis happens in the cytoplasm). Its matrix holds enzymes, circular DNA and 70S ribosomes.", r: "3.1.2.1" },
  { t: "cristae", a: ["crista"], d: "The folds of the inner membrane of a mitochondrion, giving a large surface area for the enzymes and proteins that make ATP.", r: "3.1.2.1" },
  { t: "chloroplast", a: [], d: "A plant organelle with a double membrane, containing stacks of thylakoids (grana) in a fluid stroma; the site of photosynthesis.", r: "3.1.2.1" },
  { t: "thylakoid", a: [], d: "A flattened membrane sac in a chloroplast containing chlorophyll; thylakoids are stacked into grana, giving a large area for absorbing light.", r: "3.1.2.1" },
  { t: "granum", a: ["grana"], d: "A stack of thylakoids in a chloroplast.", r: "3.1.2.1" },
  { t: "stroma", a: [], d: "The fluid inside a chloroplast around the grana, containing enzymes of photosynthesis, starch grains, circular DNA and 70S ribosomes.", r: "3.1.2.1" },
  { t: "Golgi apparatus", a: ["Golgi body", "Golgi"], d: "A stack of flattened membrane sacs that modifies proteins and lipids (e.g. adding carbohydrate to make glycoproteins), packages them into vesicles, and forms lysosomes.", r: "3.1.2.1" },
  { t: "vesicle", a: [], d: "A small sac bounded by a single membrane that carries substances within a cell or to the cell-surface membrane.", r: "3.1.2.1" },
  { t: "lysosome", a: [], d: "A vesicle with a single membrane, formed by the Golgi apparatus, containing hydrolytic enzymes that digest worn-out organelles and engulfed pathogens.", r: "3.1.2.1" },
  { t: "hydrolytic enzyme", a: [], d: "An enzyme that catalyses hydrolysis, such as those in lysosomes that break down pathogens and worn-out organelles.", r: "3.1.2.1" },
  { t: "ribosome", a: ["70S ribosome", "80S ribosome"], d: "A small organelle with no membrane, made of RNA and protein, where translation takes place. Eukaryotic cytoplasm has 80S ribosomes; prokaryotes, mitochondria and chloroplasts have smaller 70S ribosomes.", r: "3.1.2.1" },
  { t: "endoplasmic reticulum", a: [], d: "A network of membranes in the cytoplasm of eukaryotic cells: rough endoplasmic reticulum makes proteins, smooth endoplasmic reticulum makes lipids.", r: "3.1.2.1" },
  { t: "rough endoplasmic reticulum", a: ["rough ER", "RER"], d: "A network of flattened membrane sacs with ribosomes on the outer surface, continuous with the nuclear envelope; it synthesises and transports proteins.", r: "3.1.2.1" },
  { t: "smooth endoplasmic reticulum", a: ["smooth ER"], d: "A network of tubular membranes without ribosomes; it synthesises, stores and transports lipids and carbohydrates.", r: "3.1.2.1" },
  { t: "cell wall", a: [], d: "A layer outside the cell-surface membrane that gives strength and stops the cell bursting by osmosis: made of cellulose in plants and chitin in fungi; bacterial walls contain murein.", r: "3.1.2.1" },
  { t: "vacuole", a: ["cell vacuole"], d: "A fluid-filled sac in a plant cell, surrounded by the tonoplast, containing cell sap; it keeps the cell turgid and stores substances.", r: "3.1.2.1" },
  { t: "tonoplast", a: [], d: "The single membrane around the vacuole of a plant cell.", r: "3.1.2.1" },
  { t: "organ system", a: [], d: "A group of organs working together to perform a particular function, e.g. the digestive system.", r: "3.1.2.1" },
  { t: "epithelium", a: ["epithelial cell", "epithelia", "epithelial tissue"], d: "A tissue of closely packed cells covering a surface or lining a tube or cavity, e.g. the lining of the ileum or the walls of the alveoli.", r: "3.1.2.1" },

  // 3.1.2.2 Prokaryotic cells
  { t: "prokaryotic cell", a: ["prokaryote", "prokaryotic"], d: "A cell with no nucleus and no membrane-bound organelles: its DNA is a single circular molecule free in the cytoplasm, its ribosomes are 70S and its wall contains murein, e.g. a bacterium.", r: "3.1.2.2" },
  { t: "murein", a: ["peptidoglycan"], d: "The substance in bacterial cell walls, made of sugar chains cross-linked by short peptides (the specification calls it a glycoprotein); it gives strength and stops the cell bursting by osmosis.", r: "3.1.2.2" },
  { t: "plasmid", a: [], d: "A small, circular DNA molecule found in many prokaryotes, separate from the main circular DNA; it carries a few genes, such as genes for antibiotic resistance.", r: "3.1.2.2" },
  { t: "capsule", a: [], d: "A protective outer layer. In some bacteria, a slimy layer (mainly polysaccharide) outside the cell wall that protects against drying out and phagocytosis; around a benign tumour, a layer of tissue that contains it.", r: "3.1.2.2" },
  { t: "flagellum", a: ["flagella"], d: "A long, thin structure used for movement. A bacterial flagellum rotates to drive the cell; the flagellum (tail) of a sperm cell beats to make it swim.", r: "3.1.2.2" },
  { t: "nucleoid", a: [], d: "The region of a prokaryotic cell's cytoplasm where its circular DNA lies; it has no surrounding membrane.", r: "3.1.2.2" },

  // 3.1.3.1 Enzymes and enzyme action
  { t: "enzyme", a: [], d: "A globular protein that acts as a biological catalyst, speeding up a specific reaction by lowering its activation energy; its properties depend on the tertiary structure of its active site.", r: "3.1.3.1" },
  { t: "catalyst", a: [], d: "A substance that speeds up a chemical reaction without being used up or permanently changed.", r: "3.1.3.1" },
  { t: "active site", a: [], d: "The small region of an enzyme, formed by the folding of its polypeptide, where a complementary substrate binds and the reaction takes place.", r: "3.1.3.1" },
  { t: "substrate", a: [], d: "The molecule that binds to the active site of an enzyme and is changed in the reaction the enzyme catalyses. (A respiratory substrate, such as glucose, is a molecule broken down in respiration to release energy.)", r: "3.1.3.1" },
  { t: "complementary", a: [], d: "Fitting together in shape (and charge) so that two molecules can bind, e.g. an active site and its substrate, an antibody and its antigen; complementary bases pair by hydrogen bonds.", r: "3.1.3.1" },
  { t: "enzyme-substrate complex", a: ["enzyme–substrate complex", "enzyme substrate complex"], d: "The temporary structure formed when a substrate is bound in the complementary active site of an enzyme; the reaction takes place within it.", r: "3.1.3.1" },
  { t: "enzyme-product complex", a: ["enzyme–product complex"], d: "The brief state after the reaction when the products are still bound to the active site, before they are released.", r: "3.1.3.1" },
  { t: "activation energy", a: [], d: "The minimum energy that colliding molecules need for a reaction to take place. Enzymes lower it, so more collisions are successful.", r: "3.1.3.1" },
  { t: "lock and key model", a: ["lock-and-key model", "lock and key"], d: "An early model of enzyme action: the active site is a rigid shape exactly complementary to the substrate, as a key fits a lock.", r: "3.1.3.1" },
  { t: "induced fit model", a: ["induced-fit model", "induced fit", "induced-fit"], d: "The accepted model of enzyme action: substrate binding causes a slight change in the tertiary structure of the active site, which moulds around the substrate and strains its bonds.", r: "3.1.3.1" },
  { t: "specificity", a: ["enzyme specificity"], d: "The property of an enzyme of catalysing only one reaction (or a few similar ones), because only a substrate complementary to its active site can bind.", r: "3.1.3.1" },
  { t: "catalase", a: [], d: "An intracellular enzyme that catalyses the breakdown of hydrogen peroxide into water and oxygen.", r: "3.1.3.1" },
  { t: "lysozyme", a: [], d: "An enzyme that hydrolyses bacterial cell walls; found in tears, saliva and lysosomes.", r: "3.1.3.1" },

  // 3.1.3.2 Properties of enzymes
  { t: "optimum", a: ["optimum temperature", "optimum pH"], d: "The value of a condition, such as temperature or pH, at which an enzyme-controlled reaction is fastest. It differs between enzymes.", r: "3.1.3.2" },
  { t: "denaturation", a: ["denatured", "denature", "denaturing"], d: "Loss of a protein's tertiary structure when bonds such as hydrogen and ionic bonds break (e.g. at high temperature or extreme pH), so the active site changes shape and function is lost; peptide bonds are not broken. Usually permanent.", r: "3.1.3.2" },
  { t: "kinetic energy", a: [], d: "Energy of movement. Raising the temperature gives molecules more kinetic energy, so they collide more often and with more energy.", r: "3.1.3.2" },
  { t: "limiting factor", a: [], d: "The factor whose level limits the rate of a process at a given moment, e.g. the one in shortest supply or furthest from its optimum; increasing it increases the rate, until another factor becomes limiting.", r: "3.1.3.2" },
  { t: "initial rate", a: [], d: "The rate at the very start of a reaction, before substrate is used up; found from the gradient of a tangent drawn at time zero.", r: "3.1.3.2" },
  { t: "inhibitor", a: ["enzyme inhibitor"], d: "A substance that reduces the rate of an enzyme-controlled reaction by binding to the enzyme.", r: "3.1.3.2" },
  { t: "competitive inhibitor", a: ["competitive inhibition"], d: "An inhibitor similar in shape to the substrate that binds to the active site and blocks it. The substrate competes with it, so raising the substrate concentration reduces its effect.", r: "3.1.3.2" },
  { t: "non-competitive inhibitor", a: ["non-competitive inhibition", "noncompetitive inhibitor", "noncompetitive inhibition"], d: "An inhibitor that binds to an enzyme away from the active site, changing its tertiary structure so the active site is no longer complementary to the substrate; more substrate does not overcome it.", r: "3.1.3.2" },

  // 3.1.4.1 Plasma membranes
  { t: "fluid-mosaic model", a: ["fluid mosaic model", "fluid-mosaic", "fluid mosaic"], d: "The model of membrane structure: a phospholipid bilayer in which proteins are scattered like tiles (mosaic) and molecules can move sideways (fluid), with cholesterol, glycoproteins and glycolipids.", r: "3.1.4.1" },
  { t: "phospholipid bilayer", a: ["bilayer", "lipid bilayer"], d: "Two layers of phospholipids with their hydrophilic heads facing the water on each side and their hydrophobic tails inwards; the basic structure of all cell membranes.", r: "3.1.4.1" },
  { t: "intrinsic protein", a: ["integral protein"], d: "A membrane protein that spans the phospholipid bilayer, e.g. channel and carrier proteins.", r: "3.1.4.1" },
  { t: "extrinsic protein", a: ["peripheral protein"], d: "A membrane protein on the inner or outer surface of the membrane, or partly in one layer; it does not span the bilayer.", r: "3.1.4.1" },
  { t: "channel protein", a: [], d: "An intrinsic protein that forms a hydrophilic pore through the membrane, letting specific ions or polar molecules pass down their concentration gradient by facilitated diffusion.", r: "3.1.4.1" },
  { t: "carrier protein", a: [], d: "An intrinsic protein that binds a specific molecule or ion, changes shape and releases it on the other side of the membrane; used in facilitated diffusion and active transport.", r: "3.1.4.1" },
  { t: "glycoprotein", a: [], d: "A protein with carbohydrate chains attached. In the cell-surface membrane they face outwards and act in cell recognition, as receptors and as antigens.", r: "3.1.4.1" },
  { t: "glycolipid", a: [], d: "A lipid with a carbohydrate chain attached, on the outer surface of the cell-surface membrane; involved in cell recognition.", r: "3.1.4.1" },
  { t: "cholesterol", a: [], d: "A lipid in cell membranes that restricts the movement of other membrane molecules, making the membrane less fluid and more stable. High levels in the blood are a risk factor for coronary heart disease.", r: "3.1.4.1" },
  { t: "microvillus", a: ["microvilli"], d: "One of many tiny finger-like folds of the cell-surface membrane of a single cell, about 1 µm long, that increase its surface area for absorption.", r: "3.1.4.1" },
  { t: "partially permeable", a: ["partially permeable membrane", "selectively permeable", "selective permeability"], d: "Letting some substances through (water and small non-polar molecules) but not others (ions and large polar molecules) unless specific proteins carry them.", r: "3.1.4.1" },

  // 3.1.4.2 Diffusion
  { t: "diffusion", a: [], d: "The net, passive movement of molecules or ions from a region of higher concentration to a region of lower concentration (down a concentration gradient), caused by their random movement.", r: "3.1.4.2" },
  { t: "simple diffusion", a: [], d: "Diffusion straight through the phospholipid bilayer, possible for small, non-polar molecules such as oxygen and carbon dioxide.", r: "3.1.4.2" },
  { t: "concentration gradient", a: [], d: "A difference in concentration between two regions. Substances diffuse down a concentration gradient; active transport moves them against it.", r: "3.1.4.2" },
  { t: "passive", a: [], d: "Not using energy from ATP; diffusion, facilitated diffusion and osmosis are passive and rely on the kinetic energy of the molecules.", r: "3.1.4.2" },
  { t: "facilitated diffusion", a: [], d: "The passive movement of ions or polar molecules down a concentration gradient through specific channel or carrier proteins in a membrane; no ATP is used.", r: "3.1.4.2" },
  { t: "osmosis", a: [], d: "The net movement of water molecules from a solution of higher water potential to one of lower water potential through a partially permeable membrane; a special case of diffusion.", r: "3.1.4.2" },
  { t: "water potential", a: [], d: "A measure of the tendency of water to move out of a solution, in kPa. Pure water has the highest value, 0 kPa; adding solutes makes it more negative.", r: "3.1.4.2" },
  { t: "pressure potential", a: [], d: "The pressure of a plant cell's contents against its cell wall; it raises the cell's water potential, so a turgid cell stops taking in water.", r: "3.1.4.2" },
  { t: "turgid", a: [], d: "Describes a plant cell that has taken in water by osmosis until its contents press firmly against the cell wall.", r: "3.1.4.2" },
  { t: "flaccid", a: [], d: "Describes a plant cell that has lost water, so its contents no longer press against the cell wall.", r: "3.1.4.2" },
  { t: "plasmolysis", a: ["plasmolysed"], d: "Shrinkage of the cytoplasm and vacuole of a plant cell away from the cell wall, when water leaves by osmosis into a solution of lower water potential.", r: "3.1.4.2" },
  { t: "isotonic", a: [], d: "Describes a solution with the same water potential as a cell, so there is no net movement of water by osmosis.", r: "3.1.4.2" },
  { t: "hypotonic", a: [], d: "Describes a solution with a higher water potential than a cell (less concentrated), so water enters the cell by osmosis.", r: "3.1.4.2" },
  { t: "hypertonic", a: [], d: "Describes a solution with a lower water potential than a cell (more concentrated), so water leaves the cell by osmosis.", r: "3.1.4.2" },
  { t: "lysis", a: ["lysed"], d: "The bursting of a cell, e.g. an animal cell in pure water, or a host cell when new virus particles are released.", r: "3.1.4.2" },
  { t: "Fick's law", a: ["Fick’s law"], d: "Rate of diffusion is proportional to surface area × difference in concentration ÷ thickness of the exchange surface.", r: "3.1.4.2" },

  // 3.1.4.3 Active transport
  { t: "active transport", a: [], d: "The movement of molecules or ions across a membrane from a lower to a higher concentration (against the gradient), through specific carrier proteins, using energy from the hydrolysis of ATP.", r: "3.1.4.3" },
  { t: "ATP", a: ["adenosine triphosphate"], d: "Adenosine triphosphate: a nucleotide whose hydrolysis to ADP and inorganic phosphate releases energy in small amounts; the immediate source of energy for biological processes.", r: "3.1.4.3" },
  { t: "ADP", a: ["adenosine diphosphate"], d: "Adenosine diphosphate: formed when ATP is hydrolysed; it is joined to inorganic phosphate by condensation to re-form ATP, using energy from respiration (or, in chloroplasts, from light in photosynthesis).", r: "3.1.4.3" },
  { t: "inorganic phosphate", a: [], d: "A phosphate ion (Pi), released when ATP is hydrolysed and used with ADP to make ATP.", r: "3.1.4.3" },
  { t: "ATP synthase", a: [], d: "The enzyme that catalyses the synthesis of ATP from ADP and inorganic phosphate, a condensation reaction.", r: "3.1.4.3" },
  { t: "ATP hydrolase", a: [], d: "The enzyme that catalyses the hydrolysis of ATP to ADP and inorganic phosphate, releasing energy.", r: "3.1.4.3" },
  { t: "sodium-potassium pump", a: ["sodium–potassium pump", "sodium potassium pump", "Na⁺/K⁺ pump", "Na+/K+ pump", "Na⁺–K⁺ pump"], d: "A carrier protein that uses energy from the hydrolysis of ATP to actively transport three sodium ions out of a cell and two potassium ions in.", r: "3.1.4.3" },
  { t: "respiratory inhibitor", a: ["metabolic inhibitor"], d: "A substance, such as cyanide, that stops respiration so no ATP is made; it stops active transport, showing that the process needs ATP.", r: "3.1.4.3" },

  // 3.1.5.1 Surface area to volume
  { t: "surface area to volume ratio", a: ["SA:V", "SA : V", "surface area:volume ratio", "surface area to volume relationship"], d: "Surface area divided by volume. It falls as an organism gets larger, so a large organism has less exchange surface for each unit of its volume.", r: "3.1.5.1" },
  { t: "diffusion distance", a: ["diffusion pathway"], d: "The distance across which a substance must diffuse, e.g. the thickness of an exchange surface; the shorter it is, the faster the rate of diffusion.", r: "3.1.5.1" },
  { t: "exchange surface", a: [], d: "A surface across which substances pass between an organism and its surroundings, or between blood and cells. Efficient ones have a large surface area, are thin and keep a steep concentration gradient.", r: "3.1.5.1" },
  { t: "mass transport", a: ["mass transport system"], d: "The bulk movement of a fluid, and everything carried in it, through an organism, driven by a pressure difference, e.g. blood pumped by the heart.", r: "3.1.5.1" },
  { t: "metabolic rate", a: [], d: "The rate at which an organism's chemical reactions use energy (and oxygen); it is high in small, active mammals.", r: "3.1.5.1" },

  // 3.1.5.2 Gas exchange
  { t: "gas exchange", a: ["gas-exchange"], d: "The diffusion of oxygen and carbon dioxide between an organism and its surroundings across an exchange surface.", r: "3.1.5.2" },
  { t: "gas exchange system", a: ["gas-exchange system"], d: "The structures an organism uses for gas exchange, e.g. the tracheal system of an insect or the lungs and airways of a mammal; one of a mammal's interfaces with the environment.", r: "3.1.5.2" },
  { t: "tracheal system", a: [], d: "The gas exchange system of an insect: a network of air-filled tubes (tracheae and tracheoles) that opens at spiracles and carries air directly to the cells.", r: "3.1.5.2" },
  { t: "spiracle", a: [], d: "An opening in the body wall of an insect through which air enters and leaves the tracheae; valves can close it to reduce water loss.", r: "3.1.5.2" },
  { t: "trachea", a: ["tracheae"], d: "In mammals, the windpipe: the airway from the throat to the bronchi, held open by C-shaped rings of cartilage. In insects, tracheae are air-filled tubes strengthened by rings of chitin.", r: "3.1.5.2" },
  { t: "tracheole", a: [], d: "A very fine, thin-walled branch of an insect trachea ending among the cells; oxygen dissolves in the fluid at its tip and diffuses into the cells.", r: "3.1.5.2" },
  { t: "chitin", a: [], d: "A tough, nitrogen-containing structural polysaccharide that forms the exoskeleton of insects and the rings holding their tracheae open; also found in fungal cell walls.", r: "3.1.5.2" },
  { t: "stoma", a: ["stomata", "stomatal"], d: "A pore in the epidermis of a leaf, between two guard cells, through which carbon dioxide and oxygen diffuse and water vapour is lost.", r: "3.1.5.2" },
  { t: "guard cell", a: [], d: "One of a pair of cells around a stoma; they become turgid to open the stoma and flaccid to close it.", r: "3.1.5.2" },
  { t: "spongy mesophyll", a: [], d: "Loosely packed cells in a leaf with large air spaces between them, giving a large, moist surface for gas exchange.", r: "3.1.5.2" },
  { t: "palisade mesophyll", a: [], d: "Tightly packed, column-shaped leaf cells beneath the upper epidermis, with many chloroplasts; the main site of photosynthesis.", r: "3.1.5.2" },
  { t: "air space", a: ["intercellular air space"], d: "A gap between the mesophyll cells of a leaf, connected to the stomata, through which gases diffuse quickly.", r: "3.1.5.2" },
  { t: "xerophyte", a: ["xerophytic", "xerophytic plant"], d: "A plant adapted to living where water is scarce, with features that reduce water loss, e.g. a thick waxy cuticle, sunken stomata, hairs and rolled leaves.", r: "3.1.5.2" },
  { t: "cuticle", a: [], d: "A waterproof, waxy outer layer of a leaf, or of an insect's exoskeleton, that reduces water loss.", r: "3.1.5.2" },
  { t: "dicotyledonous plant", a: ["dicotyledonous", "dicotyledon", "dicot"], d: "A flowering plant whose seeds have two seed leaves (cotyledons), usually with broad leaves, e.g. a buttercup.", r: "3.1.5.2" },
  { t: "bronchus", a: ["bronchi"], d: "One of the two airways that branch from the trachea, one to each lung, held open by cartilage.", r: "3.1.5.2" },
  { t: "bronchiole", a: [], d: "A small airway that branches from a bronchus and leads to the alveoli; it has smooth muscle in its wall but no cartilage.", r: "3.1.5.2" },
  { t: "alveolus", a: ["alveoli"], d: "A tiny air sac at the end of a bronchiole, surrounded by capillaries; its wall of squamous epithelium is one cell thick. The site of gas exchange in the lungs.", r: "3.1.5.2" },
  { t: "alveolar epithelium", a: [], d: "The single layer of thin, flattened (squamous) cells forming the wall of an alveolus; with the capillary wall it gives a very short diffusion distance.", r: "3.1.5.2" },
  { t: "squamous epithelium", a: ["squamous"], d: "Epithelium of thin, flat cells, e.g. the wall of an alveolus, giving a short diffusion distance.", r: "3.1.5.2" },
  { t: "ventilation", a: ["ventilate", "ventilated"], d: "Moving air (or water) into and out of a gas exchange system; it keeps the concentration gradients at the exchange surface steep.", r: "3.1.5.2" },
  { t: "diaphragm", a: [], d: "A dome of muscle below the lungs; it contracts and flattens in inspiration, increasing the volume of the thoracic cavity.", r: "3.1.5.2" },
  { t: "intercostal muscles", a: ["intercostal muscle", "external intercostal muscles", "internal intercostal muscles", "external intercostals", "internal intercostals", "intercostals"], d: "Muscles between the ribs. The external intercostals contract in inspiration, moving the ribs up and out; the internal intercostals contract in forced expiration, moving them down and in.", r: "3.1.5.2" },
  { t: "inspiration", a: ["inhalation"], d: "Breathing in: the diaphragm and external intercostal muscles contract, the volume of the thoracic cavity increases, pressure in the lungs falls below atmospheric pressure and air flows in.", r: "3.1.5.2" },
  { t: "expiration", a: ["exhalation"], d: "Breathing out: at rest the diaphragm and external intercostal muscles relax and the lungs recoil, so thoracic volume falls, pressure rises above atmospheric and air flows out.", r: "3.1.5.2" },
  { t: "thoracic cavity", a: ["thorax"], d: "The space in the chest enclosed by the ribs and the diaphragm, containing the lungs and the heart. (In insects, the thorax is the middle section of the body.)", r: "3.1.5.2" },
  { t: "tidal volume", a: [], d: "The volume of air breathed in or out in one breath.", r: "3.1.5.2" },
  { t: "ventilation rate", a: ["pulmonary ventilation rate", "pulmonary ventilation"], d: "The volume of air breathed in per minute: tidal volume × breathing rate.", r: "3.1.5.2" },
  { t: "breathing rate", a: [], d: "The number of breaths taken per minute.", r: "3.1.5.2" },
  { t: "FEV1", a: ["FEV₁", "forced expiratory volume"], d: "Forced expiratory volume in one second: the volume of air a person can breathe out in the first second of a forced breath out; it is reduced when the airways are narrowed.", r: "3.1.5.2" },
  { t: "FVC", a: ["forced vital capacity"], d: "Forced vital capacity: the largest volume of air that can be breathed out forcefully after the deepest possible breath in.", r: "3.1.5.2" },

  // 3.1.5.3 Haemoglobin and circulation
  { t: "double circulation", a: [], d: "A circulation in which blood passes through the heart twice in each complete circuit: the pulmonary circuit to the lungs and the systemic circuit to the rest of the body.", r: "3.1.5.3" },
  { t: "haemoglobin", a: [], d: "The oxygen-carrying protein in red blood cells. In adult humans it has four polypeptide globin chains, each with an iron-containing haem group that binds one oxygen molecule.", r: "3.1.5.3" },
  { t: "haem", a: ["haem group"], d: "The iron-containing group associated with each globin chain of haemoglobin; its iron ion (Fe²⁺) binds one oxygen molecule.", r: "3.1.5.3" },
  { t: "globin", a: [], d: "One of the polypeptide chains of haemoglobin, each associated with a haem group.", r: "3.1.5.3" },
  { t: "red blood cell", a: ["erythrocyte"], d: "A biconcave cell with no nucleus, packed with haemoglobin, that transports oxygen; its shape gives a large surface area to volume ratio.", r: "3.1.5.3" },
  { t: "partial pressure", a: ["partial pressure of oxygen", "partial pressure of carbon dioxide", "pO₂", "pO2", "pCO₂", "pCO2"], d: "The pressure exerted by one gas in a mixture, a measure of how much of it is present; for oxygen written pO₂, in kPa.", r: "3.1.5.3" },
  { t: "oxygen dissociation curve", a: ["oxygen-haemoglobin dissociation curve", "oxygen–haemoglobin dissociation curve", "oxyhaemoglobin dissociation curve", "dissociation curve"], d: "A graph of the percentage saturation of haemoglobin with oxygen against the partial pressure of oxygen. It is S-shaped (sigmoid) because of cooperative binding.", r: "3.1.5.3" },
  { t: "percentage saturation", a: [], d: "The proportion of haemoglobin's oxygen-binding sites that are occupied, as a percentage of the maximum.", r: "3.1.5.3" },
  { t: "loading", a: [], d: "Taking a substance on. For haemoglobin, binding oxygen (association) at high pO₂, in the lungs. In phloem, moving sucrose into the sieve tubes at a source.", r: "3.1.5.3" },
  { t: "unloading", a: [], d: "Releasing a substance. For haemoglobin, releasing oxygen (dissociation) at low pO₂, in respiring tissues. In phloem, removing sucrose from the sieve tubes at a sink.", r: "3.1.5.3" },
  { t: "affinity", a: [], d: "How readily a molecule binds another. Haemoglobin with a high affinity for oxygen loads it easily but unloads it less readily; its dissociation curve lies further to the left.", r: "3.1.5.3" },
  { t: "cooperative binding", a: ["co-operative binding", "cooperative loading"], d: "The binding of the first oxygen molecule changes the shape of haemoglobin, making it easier for further oxygen molecules to bind; this gives the S-shaped dissociation curve.", r: "3.1.5.3" },
  { t: "Bohr effect", a: ["Bohr shift"], d: "A higher partial pressure of carbon dioxide lowers haemoglobin's affinity for oxygen, shifting the dissociation curve to the right, so more oxygen is unloaded in actively respiring tissues.", r: "3.1.5.3" },
  { t: "fetal haemoglobin", a: [], d: "The haemoglobin of a fetus. It has a higher affinity for oxygen than adult haemoglobin (curve to the left), so it can take oxygen from the mother's blood in the placenta.", r: "3.1.5.3" },
  { t: "aorta", a: [], d: "The largest artery, which carries oxygenated blood from the left ventricle to the body.", r: "3.1.5.3" },
  { t: "vena cava", a: ["venae cavae"], d: "One of the two large veins (the superior and inferior venae cavae) that return deoxygenated blood from the body to the right atrium.", r: "3.1.5.3" },
  { t: "pulmonary artery", a: [], d: "The artery that carries deoxygenated blood from the right ventricle to the lungs.", r: "3.1.5.3" },
  { t: "pulmonary vein", a: [], d: "The vein that carries oxygenated blood from the lungs to the left atrium.", r: "3.1.5.3" },
  { t: "coronary artery", a: ["coronary arteries"], d: "One of the arteries that branch from the aorta just above the aortic valve and supply the heart muscle with oxygenated blood.", r: "3.1.5.3" },
  { t: "hepatic artery", a: [], d: "The artery that carries oxygenated blood from the aorta to the liver.", r: "3.1.5.3" },
  { t: "hepatic portal vein", a: [], d: "The vein that carries blood rich in absorbed nutrients from the gut to the liver; it links two capillary beds.", r: "3.1.5.3" },
  { t: "hepatic vein", a: [], d: "The vein that carries blood from the liver to the vena cava.", r: "3.1.5.3" },

  // 3.1.6 Variation
  { t: "intraspecific variation", a: [], d: "Variation between members of the same species.", r: "3.1.6" },
  { t: "interspecific variation", a: [], d: "Variation between different species.", r: "3.1.6" },
  { t: "genotype", a: [], d: "The genetic make-up of an organism: the alleles it has.", r: "3.1.6" },
  { t: "phenotype", a: [], d: "The observable characteristics of an organism, which result from its genotype, its environment and how they interact.", r: "3.1.6" },
  { t: "random sampling", a: ["random sample", "randomly sampled"], d: "Choosing a sample so that every individual has an equal chance of being selected, e.g. using random numbers as coordinates for quadrats; it avoids sampling bias.", r: "3.1.6" },
  { t: "bias", a: ["sampling bias", "biased", "selection bias"], d: "A systematic error that pushes results one way, e.g. from how a sample or participants were chosen (sampling or selection bias) or from how people report past exposures (recall bias); repeating the measurements the same way does not remove it.", r: "3.1.6" },
  { t: "representative", a: ["representative sample"], d: "Describes a sample whose values are spread like those of the whole population; achieved by random selection and an adequate sample size.", r: "3.1.6" },
  { t: "sample size", a: [], d: "The number of individuals or measurements in a sample. Larger random samples are more likely to be representative, and the effect of chance on the result is smaller.", r: "3.1.6" },
  { t: "normal distribution", a: [], d: "A symmetrical, bell-shaped distribution of a continuously varying characteristic, with most values close to the mean and fewer towards the extremes.", r: "3.1.6" },
  { t: "standard deviation", a: [], d: "A measure of the spread of values about the mean: the larger it is, the more variation. In a normal distribution about 68 % of values lie within one standard deviation of the mean.", r: "3.1.6" },
  { t: "continuous variation", a: [], d: "Variation in which a characteristic can take any value within a range, e.g. height; usually affected by many genes and the environment.", r: "3.1.6" },
  { t: "discontinuous variation", a: [], d: "Variation in which individuals fall into distinct categories with no intermediates, e.g. ABO blood group; usually controlled by one or a few genes.", r: "3.1.6" },
  { t: "correlation", a: [], d: "A relationship in which one variable changes together with another. A correlation does not show that one variable causes the change in the other.", r: "3.1.6" },
  { t: "causation", a: ["causal link", "causal relationship"], d: "A relationship in which a change in one variable directly brings about a change in another; showing it needs more than a correlation, e.g. a controlled experiment or a mechanism.", r: "3.1.6" },
  { t: "confounding variable", a: ["confounder", "confounding factor", "confounding"], d: "A third variable that affects both of the variables being compared, so it can create or hide an apparent link between them.", r: "3.1.6" },

  // 3.1.7.1 Nucleic acids
  { t: "nucleotide", a: [], d: "The monomer of DNA and RNA, made of a pentose sugar, a phosphate group and a nitrogen-containing organic base.", r: "3.1.7.1" },
  { t: "nucleic acid", a: [], d: "A polymer of nucleotides: DNA or RNA.", r: "3.1.7.1" },
  { t: "pentose", a: [], d: "A sugar with five carbon atoms: deoxyribose in DNA nucleotides, ribose in RNA nucleotides.", r: "3.1.7.1" },
  { t: "deoxyribose", a: [], d: "The pentose sugar in DNA nucleotides; it has one less oxygen atom than ribose.", r: "3.1.7.1" },
  { t: "ribose", a: [], d: "The pentose sugar in RNA nucleotides.", r: "3.1.7.1" },
  { t: "nitrogen-containing base", a: ["organic base", "nitrogenous base", "nitrogen-containing organic base"], d: "The part of a nucleotide that varies: adenine, cytosine, guanine and thymine in DNA; uracil replaces thymine in RNA.", r: "3.1.7.1" },
  { t: "adenine", a: [], d: "A nitrogen-containing base (a purine) found in DNA and RNA; it pairs with thymine in DNA and with uracil in RNA.", r: "3.1.7.1" },
  { t: "thymine", a: [], d: "A nitrogen-containing base (a pyrimidine) found only in DNA; it pairs with adenine.", r: "3.1.7.1" },
  { t: "cytosine", a: [], d: "A nitrogen-containing base (a pyrimidine) found in DNA and RNA; it pairs with guanine.", r: "3.1.7.1" },
  { t: "guanine", a: [], d: "A nitrogen-containing base (a purine) found in DNA and RNA; it pairs with cytosine.", r: "3.1.7.1" },
  { t: "uracil", a: [], d: "A nitrogen-containing base (a pyrimidine) found in RNA in place of thymine; it pairs with adenine.", r: "3.1.7.1" },
  { t: "purine", a: [], d: "A base with two rings: adenine or guanine. Each base pair is one purine with one pyrimidine.", r: "3.1.7.1" },
  { t: "pyrimidine", a: [], d: "A base with one ring: cytosine, thymine or uracil.", r: "3.1.7.1" },
  { t: "polynucleotide", a: [], d: "A chain of many nucleotides joined by phosphodiester bonds formed by condensation.", r: "3.1.7.1" },
  { t: "phosphodiester bond", a: [], d: "The covalent bond, formed by condensation, between the phosphate group of one nucleotide and the pentose of the next in a polynucleotide.", r: "3.1.7.1" },
  { t: "sugar-phosphate backbone", a: ["sugar–phosphate backbone"], d: "The alternating chain of pentose sugars and phosphate groups, joined by phosphodiester bonds, that runs along each polynucleotide strand with the bases attached to it.", r: "3.1.7.1" },
  { t: "double helix", a: [], d: "The structure of DNA: two antiparallel polynucleotide strands wound around each other, held together by hydrogen bonds between complementary base pairs.", r: "3.1.7.1" },
  { t: "complementary base pairing", a: ["complementary base pair", "complementary bases", "base pairing", "base pair"], d: "The pairing of bases by hydrogen bonds: adenine with thymine (or with uracil in RNA) and cytosine with guanine.", r: "3.1.7.1" },
  { t: "antiparallel", a: [], d: "Running in opposite directions: the two strands of DNA run one 5′ to 3′ and the other 3′ to 5′.", r: "3.1.7.1" },
  { t: "Chargaff's rules", a: ["Chargaff’s rules"], d: "In double-stranded DNA the amount of adenine equals that of thymine, and the amount of cytosine equals that of guanine, because of complementary base pairing.", r: "3.1.7.1" },
  { t: "mRNA", a: ["messenger RNA"], d: "Messenger RNA: a single, linear strand of RNA, complementary to the template strand of a gene, that carries the code as codons from the DNA to the ribosomes.", r: "3.1.7.1" },
  { t: "tRNA", a: ["transfer RNA"], d: "Transfer RNA: a single RNA strand folded into a clover-leaf shape by hydrogen bonds between bases, with an anticodon on one loop and an amino acid binding site; it carries a specific amino acid to the ribosome.", r: "3.1.7.1" },
  { t: "codon", a: [], d: "A sequence of three bases on mRNA that codes for one amino acid (or is a start or stop codon).", r: "3.1.7.1" },
  { t: "anticodon", a: [], d: "A sequence of three unpaired bases on a tRNA molecule, complementary to a codon on mRNA.", r: "3.1.7.1" },
  { t: "amino acid binding site", a: ["amino-acid binding site", "amino acid attachment site"], d: "The end of a tRNA molecule to which its specific amino acid is attached.", r: "3.1.7.1" },

  // 3.1.7.2 DNA, genes and chromosomes
  { t: "chromosome", a: [], d: "In a eukaryotic nucleus, a long, linear DNA molecule packaged with proteins, including histones. After replication, it consists of two sister chromatids joined at the centromere.", r: "3.1.7.2" },
  { t: "histone", a: [], d: "A protein that DNA winds around; histones package and order the DNA in a eukaryotic nucleus to form chromosomes.", r: "3.1.7.2" },
  { t: "nucleosome", a: [], d: "A length of DNA wrapped around a core of eight histone proteins: the basic unit of DNA packaging in chromosomes.", r: "3.1.7.2" },
  { t: "circular DNA", a: [], d: "DNA in a closed loop, found in prokaryotes, mitochondria and chloroplasts; it is shorter than nuclear DNA and not associated with histone proteins.", r: "3.1.7.2" },
  { t: "gene", a: [], d: "A section of DNA that codes for a polypeptide; its base sequence determines the amino acid sequence. Genes determine the nature and development of an organism.", r: "3.1.7.2" },
  { t: "locus", a: ["loci"], d: "The fixed position that a gene occupies on a particular DNA molecule (chromosome).", r: "3.1.7.2" },
  { t: "allele", a: [], d: "One of the different versions of a gene, with a different base sequence; alleles of a gene occupy the same locus.", r: "3.1.7.2" },
  { t: "exon", a: [], d: "A sequence within a gene that codes for amino acids; exons are joined together when pre-mRNA is spliced.", r: "3.1.7.2" },
  { t: "intron", a: [], d: "A non-coding sequence within a eukaryotic gene that separates the exons; introns are removed from pre-mRNA by splicing.", r: "3.1.7.2" },
  { t: "non-coding multiple repeats", a: ["multiple repeats", "non-coding repeats"], d: "Short base sequences repeated many times in the DNA between genes in eukaryotes; they do not code for polypeptides.", r: "3.1.7.2" },
  { t: "non-coding DNA", a: [], d: "DNA that does not code for polypeptides, such as introns and the multiple repeats between genes; most of the nuclear DNA of eukaryotes.", r: "3.1.7.2" },
  { t: "genome", a: [], d: "The complete set of genes in a cell.", r: "3.1.7.2" },

  // 3.1.7.3 DNA replication
  { t: "DNA replication", a: [], d: "The copying of a DNA molecule by semi-conservative replication; in eukaryotes it happens in the S phase of interphase.", r: "3.1.7.3" },
  { t: "semi-conservative replication", a: ["semi-conservative", "semiconservative replication"], d: "DNA replication in which each new molecule consists of one strand from the original molecule and one newly made strand.", r: "3.1.7.3" },
  { t: "conservative replication", a: [], d: "A rejected hypothesis of DNA replication in which the original molecule stays intact and the copy is made entirely of new strands.", r: "3.1.7.3" },
  { t: "dispersive replication", a: [], d: "A rejected hypothesis of DNA replication in which every strand of both new molecules is a mixture of old and new DNA.", r: "3.1.7.3" },
  { t: "DNA helicase", a: ["helicase"], d: "The enzyme that unwinds the DNA double helix and breaks the hydrogen bonds between complementary base pairs, separating the two strands for replication.", r: "3.1.7.3" },
  { t: "DNA polymerase", a: [], d: "The enzyme that joins adjacent DNA nucleotides of a new strand during replication, forming phosphodiester bonds by condensation.", r: "3.1.7.3" },

  // 3.1.8.1 The genetic code
  { t: "genetic code", a: [], d: "The sequence of base triplets in DNA (codons in mRNA) that code for specific amino acids. It is universal, non-overlapping and degenerate.", r: "3.1.8.1" },
  { t: "base triplet", a: ["triplet"], d: "A sequence of three DNA bases that codes for one amino acid; its mRNA copy is a codon.", r: "3.1.8.1" },
  { t: "non-overlapping", a: ["non-overlapping code"], d: "Describes the genetic code: each base is part of only one triplet, and triplets are read one after another from a fixed start.", r: "3.1.8.1" },
  { t: "degenerate", a: ["degenerate code"], d: "Describes the genetic code: most amino acids are coded for by more than one triplet, so some base changes do not change the amino acid.", r: "3.1.8.1" },
  { t: "start codon", a: [], d: "The codon at which translation begins (it also codes for methionine); it sets the reading frame.", r: "3.1.8.1" },
  { t: "stop codon", a: [], d: "A codon that does not code for any amino acid; translation ends there and the polypeptide is released.", r: "3.1.8.1" },
  { t: "reading frame", a: [], d: "The way a base sequence is divided into successive triplets from the start codon; shifting it by one base changes every codon after the shift.", r: "3.1.8.1" },

  // 3.1.8.2 Polypeptide synthesis
  { t: "transcription", a: [], d: "The production of mRNA from DNA: RNA polymerase joins RNA nucleotides that pair with the template strand of a gene. In eukaryotes the product is pre-mRNA.", r: "3.1.8.2" },
  { t: "template strand", a: [], d: "The DNA strand that is read and copied by complementary base pairing, during transcription or replication; the mRNA is complementary to it.", r: "3.1.8.2" },
  { t: "coding strand", a: [], d: "The DNA strand that is not transcribed; it has the same base sequence as the mRNA, except that it has T where the mRNA has U.", r: "3.1.8.2" },
  { t: "RNA polymerase", a: [], d: "The enzyme that joins RNA nucleotides together during transcription, forming an RNA strand complementary to the template strand of DNA.", r: "3.1.8.2" },
  { t: "pre-mRNA", a: [], d: "The RNA made by transcription of a eukaryotic gene, a copy of both its exons and its introns; it is spliced to form mRNA.", r: "3.1.8.2" },
  { t: "splicing", a: ["spliced"], d: "The removal of introns from pre-mRNA and the joining of the exons, forming mRNA, in the nucleus of a eukaryotic cell.", r: "3.1.8.2" },
  { t: "translation", a: [], d: "The production of a polypeptide from the sequence of codons on mRNA at a ribosome, using tRNA molecules that carry specific amino acids, with energy from ATP.", r: "3.1.8.2" },
  { t: "polysome", a: [], d: "Several ribosomes translating the same mRNA molecule at once, so many copies of the polypeptide are made quickly.", r: "3.1.8.2" },

  // 3.1.8.3 Protein folding
  { t: "protein folding", a: [], d: "The process by which a polypeptide folds into its characteristic three-dimensional structure, determined by its amino acid sequence.", r: "3.1.8.3" },
  { t: "chaperone", a: ["chaperone protein", "chaperonin"], d: "A specialised protein that assists the folding of other proteins, e.g. by shielding exposed hydrophobic regions so the chain does not misfold or stick to other molecules.", r: "3.1.8.3" },
  { t: "heat-shock protein", a: ["heat shock protein"], d: "A chaperone made in larger amounts at high temperatures, which helps partly unfolded proteins refold and stops them clumping together.", r: "3.1.8.3" },

  // 3.1.9.1 Meiosis
  { t: "meiosis", a: [], d: "A type of nuclear division, with two divisions, that produces four genetically different haploid daughter cells from one diploid cell.", r: "3.1.9.1" },
  { t: "haploid", a: [], d: "Having one set of chromosomes (n), one from each homologous pair, as in gametes.", r: "3.1.9.1" },
  { t: "diploid", a: [], d: "Having two sets of chromosomes (2n), in homologous pairs, as in most body cells.", r: "3.1.9.1" },
  { t: "homologous chromosomes", a: ["homologous chromosome", "homologous pair", "homologue"], d: "A pair of chromosomes, one maternal and one paternal, with the same genes at the same loci; their alleles may differ.", r: "3.1.9.1" },
  { t: "chromatid", a: [], d: "One of the two identical copies of a chromosome made by DNA replication; each chromatid is one DNA molecule.", r: "3.2.10.1" },
  { t: "sister chromatid", a: [], d: "One of the two identical chromatids of a replicated chromosome, joined to the other at the centromere.", r: "3.2.10.1" },
  { t: "non-sister chromatid", a: [], d: "A chromatid from the other chromosome of a homologous pair; crossing over happens between non-sister chromatids.", r: "3.1.9.1" },
  { t: "independent segregation", a: ["independent assortment"], d: "In the first division of meiosis, each homologous pair lines up independently of the others, so daughter cells receive different combinations of maternal and paternal chromosomes.", r: "3.1.9.1" },
  { t: "crossing over", a: ["crossing-over", "crossover"], d: "The exchange of equivalent sections between non-sister chromatids of a homologous pair at chiasmata in the first division of meiosis, producing new combinations of alleles.", r: "3.1.9.1" },
  { t: "chiasma", a: ["chiasmata"], d: "A point where non-sister chromatids of a homologous pair cross and are joined; where they break and rejoin in crossing over.", r: "3.1.9.1" },
  { t: "recombinant", a: ["recombinant chromatid"], d: "A chromatid, produced by crossing over, that carries a combination of alleles not present on either parental chromosome. (Recombinant DNA, in genetic engineering, is DNA joined from different sources.)", r: "3.1.9.1" },
  { t: "bivalent", a: [], d: "A pair of homologous chromosomes lying together in the first division of meiosis.", r: "3.1.9.1" },
  { t: "gamete", a: [], d: "A haploid sex cell, such as a sperm or an egg, which fuses with another gamete at fertilisation.", r: "3.1.9.1" },
  { t: "fertilisation", a: ["fertilization"], d: "The fusion of the nuclei of a male and a female gamete, forming a diploid zygote.", r: "3.1.9.1" },
  { t: "random fertilisation", a: [], d: "Any male gamete can fuse with any female gamete, so each zygote has a chance combination of alleles; this increases genetic variation within a species.", r: "3.1.9.1" },
  { t: "zygote", a: [], d: "The diploid cell formed when two gametes fuse at fertilisation.", r: "3.1.9.1" },

  // 3.1.10.1 and 3.1.10.2 Species and taxonomy
  { t: "species", a: [], d: "The basic unit of biological classification: the largest group of organisms capable of interbreeding and producing fertile offspring.", r: "3.1.10.1" },
  { t: "binomial", a: ["binomial name", "binomial system"], d: "The two-part scientific name of a species: the genus name (capital letter) then the species name (lower case), in italics, e.g. Homo sapiens.", r: "3.1.10.1" },
  { t: "genus", a: ["genera"], d: "A group of similar, closely related species; its name is the first word of the binomial.", r: "3.1.10.1" },
  { t: "hybrid", a: [], d: "The offspring of a cross between two different species, e.g. a mule from a horse and a donkey; hybrids are often sterile. (In DNA replication experiments, hybrid DNA has one ¹⁵N strand and one ¹⁴N strand.)", r: "3.1.10.1" },
  { t: "reproductive isolation", a: ["reproductively isolated"], d: "The situation in which two populations do not interbreed and produce fertile offspring, e.g. because of different behaviour or physical incompatibility.", r: "3.1.10.1" },
  { t: "biological classification", a: [], d: "Arranging species into groups that reflect their relationships and may reflect their evolutionary origins, in a hierarchy of smaller groups within larger groups.", r: "3.1.10.2" },
  { t: "taxonomy", a: [], d: "The science of naming, describing and classifying organisms.", r: "3.1.10.2" },
  { t: "taxon", a: ["taxa"], d: "Any group in a classification hierarchy, at any rank, e.g. the family Felidae.", r: "3.1.10.2" },
  { t: "taxonomic hierarchy", a: ["hierarchy"], d: "A system in which smaller groups are placed within larger groups, with no overlap: domain, kingdom, phylum, class, order, family, genus, species.", r: "3.1.10.2" },
  { t: "phylum", a: ["phyla"], d: "The taxon below kingdom and above class in the taxonomic hierarchy.", r: "3.1.10.2" },
  { t: "immunological comparison", a: [], d: "Comparing a protein, such as albumin, between species using antibodies: the more precipitate forms with antiserum against one species' protein, the more similar the proteins and the more closely related the species.", r: "3.1.10.2" },
  { t: "genome sequencing", a: [], d: "Finding the base sequence of an organism's DNA. Comparing aligned sequences between species shows relationships: fewer differences suggests a more recent common ancestor.", r: "3.1.10.2" },
  { t: "common ancestor", a: [], d: "An ancestral species from which two or more species have evolved; closely related species share a more recent common ancestor.", r: "3.1.10.2" },

  // 3.1.11 Biodiversity
  { t: "genetic diversity", a: [], d: "The variety of alleles (and base sequences) within a population or species, or between species; measured by comparing base sequences, allele frequencies or amino acid sequences.", r: "3.1.11.1" },
  { t: "allele frequency", a: ["allele frequencies"], d: "The proportion of all copies of a gene in a population that are one particular allele; the frequencies of all alleles of a gene add up to 1.", r: "3.1.11.1" },
  { t: "base sequence", a: [], d: "The order of bases along a DNA or RNA strand; in a gene it determines the amino acid sequence of the polypeptide.", r: "3.1.11.1" },
  { t: "biodiversity", a: [], d: "The variety of living organisms in an area, including genetic diversity, species diversity and the diversity of habitats.", r: "3.1.11.2" },
  { t: "species richness", a: [], d: "A measure of the number of different species in a community.", r: "3.1.11.2" },
  { t: "species diversity", a: [], d: "Diversity that takes into account both the number of different species in a community and the number of individuals of each species.", r: "3.1.11.2" },
  { t: "index of diversity", a: ["diversity index"], d: "A value describing the relationship between the number of species in a community and the number of individuals in each: d = N(N − 1) ÷ Σn(n − 1). A higher value means more diverse.", r: "3.1.11.2" },
  { t: "community", a: ["communities"], d: "All the populations of different species living in the same area at the same time.", r: "3.1.11.2" },
  { t: "population", a: [], d: "All the organisms of one species living in the same area at the same time.", r: "3.1.11.2" },
  { t: "habitat", a: [], d: "The place where an organism lives.", r: "3.1.11.2" },
  { t: "abundance", a: [], d: "The number of individuals of a species in an area.", r: "3.1.11.2" },
  { t: "hedgerow", a: [], d: "A line of shrubs and trees between fields, giving food, shelter, nest sites and corridors for wildlife.", r: "3.1.11.2" },
  { t: "monoculture", a: [], d: "Growing a single crop species over a large area, which reduces the variety of habitats and food for other species.", r: "3.1.11.2" },
  { t: "pesticide", a: [], d: "A chemical that kills pests: insecticides kill insects and herbicides kill weeds. They can reduce biodiversity by killing non-target species and their food.", r: "3.1.11.2" },
  { t: "conservation", a: [], d: "The protection and management of species and habitats to maintain biodiversity.", r: "3.1.11.2" },
  { t: "set-aside", a: [], d: "Farmland taken out of crop production and left uncropped, providing habitats for wildlife.", r: "3.1.11.2" },
  { t: "agri-environment scheme", a: [], d: "A scheme that pays farmers to manage their land in ways that conserve biodiversity, e.g. keeping hedgerows and uncropped field margins.", r: "3.1.11.2" },

  // 3.2.1.1 Pathogens
  { t: "pathogen", a: [], d: "An agent of infection, such as a bacterium or virus, that causes disease by damaging the cells of its host, by producing toxins, or both.", r: "3.2.1.1" },
  { t: "toxin", a: [], d: "A poisonous molecule, often a protein, released by a pathogen; e.g. cholera toxin.", r: "3.2.1.1" },
  { t: "interface", a: [], d: "A surface where two things meet. For pathogens, a surface where the inside of the body meets the environment, e.g. the digestive, reproductive and gas-exchange systems.", r: "3.2.1.1" },
  { t: "infectious disease", a: ["communicable disease"], d: "A disease caused by a pathogen that can be passed from one person to another, e.g. cholera.", r: "3.2.1.1" },
  { t: "non-infectious disease", a: ["non-communicable disease"], d: "A disease that is not caused by a pathogen and cannot be caught from others, e.g. coronary heart disease and most cancers.", r: "3.2.1.1" },

  // 3.2.1.2 and 3.2.7.2 Risk factors and data
  { t: "risk factor", a: [], d: "Anything associated with an increased probability of developing a disease; it does not make the disease certain.", r: "3.2.1.2" },
  { t: "incidence", a: [], d: "The number of new cases of a disease in a population in a stated time, usually given as a rate, e.g. per 100 000 people per year.", r: "3.2.1.2" },
  { t: "mortality rate", a: ["mortality"], d: "The number of deaths from a disease in a population in a stated time, usually as a rate, e.g. per 100 000 people per year.", r: "3.2.1.2" },
  { t: "relative risk", a: [], d: "The rate of disease in people with a risk factor divided by the rate in people without it; a value of 1 means no difference.", r: "3.2.1.2" },
  { t: "absolute risk", a: ["absolute risk difference"], d: "The actual probability or rate of a disease in a group; the absolute risk difference is the rate with a factor minus the rate without it.", r: "3.2.1.2" },
  { t: "odds ratio", a: [], d: "The odds of disease in people with a factor divided by the odds in people without it; a value of 1 means no difference, below 1 means lower odds.", r: "3.2.1.2" },
  { t: "hazard ratio", a: [], d: "The rate of an outcome over time in one group divided by the rate in another; a value of 1 means no difference.", r: "3.2.7.2" },
  { t: "dose-response", a: ["dose–response", "dose-response relationship", "dose–response relationship"], d: "A pattern in which the risk of disease rises as the amount of exposure rises, e.g. more cigarettes smoked a day; evidence that strengthens a case for a causal link.", r: "3.2.1.2" },
  { t: "cohort study", a: ["cohort studies"], d: "A study that follows a large group of people forward in time and compares the incidence of disease in those with and without a risk factor.", r: "3.2.1.2" },
  { t: "case-control study", a: ["case-control studies", "case–control study"], d: "A study that compares people who have a disease (cases) with similar people who do not (controls), looking back at their past exposure to risk factors.", r: "3.2.1.2" },
  { t: "randomised controlled trial", a: ["randomized controlled trial", "RCT"], d: "A trial in which participants are allocated at random to a treatment or a control group, so other factors are balanced; the strongest test of cause.", r: "3.2.7.2" },
  { t: "placebo", a: [], d: "A dummy treatment with no active ingredient, given to a control group so that any effect of believing one is treated is the same in both groups.", r: "3.2.5.3" },
  { t: "double-blind", a: ["double blind"], d: "Describes a trial in which neither the participants nor the researchers know who is in which group, so their expectations cannot bias the results.", r: "3.2.5.3" },
  { t: "coronary heart disease", a: ["CHD"], d: "Disease in which atheroma narrows the coronary arteries, reducing the blood flow to the heart muscle; it can lead to angina and myocardial infarction.", r: "3.2.7.1" },

  // 3.2.2.1 The digestive system
  { t: "digestion", a: [], d: "The hydrolysis of large molecules into smaller ones by enzymes. In the gut it produces molecules small enough to be absorbed; inside cells, lysosome enzymes digest engulfed pathogens and worn-out organelles in the same way.", r: "3.2.2.1" },
  { t: "absorption", a: [], d: "The movement of the products of digestion from the lumen of the gut across the epithelium into the blood or lymph.", r: "3.2.2.1" },
  { t: "assimilation", a: [], d: "The use of absorbed molecules by the body's cells to make new molecules or tissues, e.g. amino acids built into proteins.", r: "3.2.2.1" },
  { t: "egestion", a: [], d: "The removal of undigested food from the gut as faeces; it is not excretion, because the material was never absorbed into cells.", r: "3.2.2.1" },
  { t: "excretion", a: [], d: "The removal of waste products of metabolism, such as urea and carbon dioxide, from the body.", r: "3.2.2.1" },
  { t: "faeces", a: [], d: "Undigested food, bacteria and dead cells egested from the rectum.", r: "3.2.2.1" },
  { t: "oesophagus", a: [], d: "The muscular tube that carries food from the mouth to the stomach by peristalsis.", r: "3.2.2.1" },
  { t: "duodenum", a: [], d: "The first part of the small intestine; it receives pancreatic juice and bile, and much of the hydrolysis of food takes place there.", r: "3.2.2.1" },
  { t: "ileum", a: [], d: "The final part of the small intestine, lined with villi and microvilli, where digestion is completed and most products of digestion are absorbed.", r: "3.2.2.1" },
  { t: "colon", a: [], d: "The main part of the large intestine; it absorbs most of the remaining water, forming faeces.", r: "3.2.2.1" },
  { t: "rectum", a: [], d: "The last part of the large intestine, which stores faeces until egestion.", r: "3.2.2.1" },
  { t: "salivary gland", a: [], d: "A gland that secretes saliva, containing salivary amylase, into the mouth.", r: "3.2.2.1" },
  { t: "pancreas", a: [], d: "A gland that secretes pancreatic juice, containing amylase, lipase and peptidases, into the duodenum.", r: "3.2.2.1" },
  { t: "pancreatic juice", a: [], d: "The secretion of the pancreas into the duodenum, containing amylase, lipase, endopeptidases and exopeptidases, and hydrogencarbonate ions that neutralise stomach acid.", r: "3.2.2.1" },
  { t: "peristalsis", a: [], d: "Waves of muscle contraction along the gut wall that push food along.", r: "3.2.2.1" },

  // 3.2.2.2 Digestion
  { t: "amylase", a: ["salivary amylase", "pancreatic amylase"], d: "An enzyme that hydrolyses the glycosidic bonds in starch, producing maltose; made by the salivary glands and the pancreas.", r: "3.2.2.2" },
  { t: "disaccharidase", a: [], d: "A membrane-bound enzyme on the epithelial cells of the ileum that hydrolyses a disaccharide into monosaccharides, e.g. maltase, sucrase and lactase.", r: "3.2.2.2" },
  { t: "maltase", a: [], d: "A membrane-bound disaccharidase that hydrolyses maltose into two glucose molecules.", r: "3.2.2.2" },
  { t: "sucrase", a: [], d: "A membrane-bound disaccharidase that hydrolyses sucrose into glucose and fructose.", r: "3.2.2.2" },
  { t: "lactase", a: [], d: "A membrane-bound disaccharidase that hydrolyses lactose into glucose and galactose.", r: "3.2.2.2" },
  { t: "lactose intolerance", a: [], d: "A condition in which too little lactase is made, so lactose is not digested; in the colon it lowers the water potential and is fermented by bacteria, causing diarrhoea.", r: "3.2.2.2" },
  { t: "lipase", a: [], d: "An enzyme that hydrolyses the ester bonds in triglycerides, producing monoglycerides and fatty acids; made by the pancreas.", r: "3.2.2.2" },
  { t: "bile", a: [], d: "A fluid made by the liver and released into the duodenum; it contains bile salts and helps neutralise stomach acid.", r: "3.2.2.2" },
  { t: "bile salts", a: ["bile salt"], d: "Molecules in bile with a hydrophobic side and a hydrophilic side; they emulsify lipids, increasing the surface area for lipase, and form micelles.", r: "3.2.2.2" },
  { t: "emulsification", a: ["emulsify", "emulsified", "emulsifies", "emulsifying"], d: "Breaking large lipid droplets into many small ones, which increases the surface area for lipase to act on; a physical process, not digestion.", r: "3.2.2.2" },
  { t: "micelle", a: [], d: "A tiny droplet of bile salts with monoglycerides and fatty acids that carries these products through the watery lumen to the epithelial cells and releases them there.", r: "3.2.2.3" },
  { t: "monoglyceride", a: [], d: "A glycerol molecule with one fatty acid attached; a product of the hydrolysis of triglycerides by lipase.", r: "3.2.2.2" },
  { t: "endopeptidase", a: [], d: "An enzyme that hydrolyses peptide bonds within a polypeptide, producing shorter polypeptides, e.g. pepsin and trypsin.", r: "3.2.2.2" },
  { t: "exopeptidase", a: [], d: "An enzyme that hydrolyses the peptide bond at one end of a polypeptide, removing a single terminal amino acid.", r: "3.2.2.2" },
  { t: "dipeptidase", a: [], d: "A membrane-bound enzyme on the epithelial cells of the ileum that hydrolyses the peptide bond in a dipeptide, releasing two amino acids.", r: "3.2.2.2" },
  { t: "membrane-bound enzyme", a: ["membrane-bound disaccharidase", "membrane-bound dipeptidase"], d: "A digestive enzyme attached to the cell-surface membrane (microvilli) of the epithelial cells of the ileum, with its active site facing the lumen.", r: "3.2.2.2" },
  { t: "pepsin", a: [], d: "An endopeptidase secreted in the stomach, with an optimum pH of about 2.", r: "3.2.2.2" },
  { t: "trypsin", a: [], d: "An endopeptidase in pancreatic juice that acts in the small intestine.", r: "3.2.2.2" },
  { t: "brush border", a: [], d: "The dense layer of microvilli on the surface of the epithelial cells of the ileum, carrying membrane-bound enzymes and transport proteins.", r: "3.2.2.2" },

  // 3.2.2.3 Absorption
  { t: "villus", a: ["villi"], d: "A finger-like fold of the lining of the small intestine, covered by many cells, containing a capillary network and a lacteal; villi greatly increase the surface area for absorption.", r: "3.2.2.3" },
  { t: "lacteal", a: [], d: "A blind-ended lymph vessel in the centre of each villus that takes up chylomicrons.", r: "3.2.2.3" },
  { t: "goblet cell", a: [], d: "A cell in the epithelium of the gut that secretes mucus.", r: "3.2.2.3" },
  { t: "co-transport", a: ["cotransport", "co-transporter", "cotransporter", "co-transporter protein", "co-transport protein", "Na⁺–glucose co-transporter"], d: "Transport of two substances together by one carrier protein (a co-transporter): one, such as sodium ions, moves down its concentration gradient and carries the other, such as glucose, against its gradient.", r: "3.2.2.3" },
  { t: "secondary active transport", a: ["indirect active transport"], d: "Co-transport that uses no ATP itself but depends on a sodium ion gradient made by the sodium-potassium pump, which does use ATP.", r: "3.2.2.3" },
  { t: "chylomicron", a: [], d: "A particle of triglycerides combined with proteins, made in the epithelial cells of the ileum and released by exocytosis into the lacteal.", r: "3.2.2.3" },
  { t: "exocytosis", a: [], d: "The release of substances from a cell when vesicles fuse with the cell-surface membrane.", r: "3.2.2.3" },

  // 3.2.3 Cholera
  { t: "cholera", a: [], d: "A disease caused by the bacterium Vibrio cholerae, spread in contaminated water or food; its toxin causes severe watery diarrhoea and dehydration.", r: "3.2.3.1" },
  { t: "cholera toxin", a: [], d: "The toxin of the cholera bacterium; it makes the epithelial cells of the small intestine secrete more chloride ions into the lumen, lowering its water potential so water follows by osmosis.", r: "3.2.3.1" },
  { t: "chloride channel", a: ["chloride channel protein"], d: "A channel protein in the apical membrane of intestinal epithelial cells through which chloride ions pass into the lumen; cholera toxin causes more of them to open.", r: "3.2.3.1" },
  { t: "apical membrane", a: [], d: "The cell-surface membrane of an epithelial cell that faces the lumen; in the small intestine it carries the microvilli.", r: "3.2.3.1" },
  { t: "diarrhoea", a: ["diarrhoeal"], d: "The frequent passing of loose, watery faeces, caused when water enters or stays in the gut lumen.", r: "3.2.3.1" },
  { t: "dehydration", a: [], d: "Loss of too much water (and ions) from the body, e.g. by severe diarrhoea; it can be fatal.", r: "3.2.3.1" },
  { t: "oral rehydration solution", a: ["ORS", "oral rehydration therapy", "oral rehydration"], d: "A solution of glucose and salts in water, drunk to replace the water and ions lost in diarrhoea; sodium and glucose are absorbed by co-transport and water follows by osmosis. It does not kill the pathogen.", r: "3.2.3.2" },
  { t: "osmolarity", a: [], d: "The total concentration of solute particles in a solution; reducing the osmolarity of ORS raises its water potential, so less water is drawn into the gut.", r: "3.2.3.2" },
  { t: "clinical trial", a: [], d: "A carefully controlled test of a treatment or vaccine on human volunteers, to find out whether it is safe and effective.", r: "3.2.3.2" },
  { t: "informed consent", a: [], d: "Agreement to take part in a trial, given freely after being told its purpose, risks, benefits and alternatives, with the right to withdraw; for young children, given by a parent or guardian.", r: "3.2.3.2" },
  { t: "clinical equipoise", a: ["equipoise"], d: "Genuine uncertainty among experts about which of two treatments is better: the condition that makes it ethical to compare them in a randomised trial.", r: "3.2.3.2" },

  // 3.2.4 HIV
  { t: "HIV", a: ["human immunodeficiency virus"], d: "Human immunodeficiency virus: an RNA virus with an envelope, whose capsid holds its RNA and the enzymes reverse transcriptase, integrase and protease; it infects CD4 helper T cells.", r: "3.2.4.1" },
  { t: "AIDS", a: ["acquired immune deficiency syndrome", "acquired immunodeficiency syndrome"], d: "Acquired immune deficiency syndrome: the most advanced stage of untreated HIV infection, when so many helper T cells are lost that opportunistic infections develop.", r: "3.2.4.2" },
  { t: "capsid", a: [], d: "The protein coat of a virus that encloses its genetic material; in HIV it also encloses reverse transcriptase, integrase and protease.", r: "3.2.4.1" },
  { t: "envelope", a: [], d: "An outer layer of membrane. In HIV, the phospholipid bilayer taken from the host cell's plasma membrane, containing viral glycoproteins. The nucleus, mitochondria and chloroplasts have a double-membrane envelope.", r: "3.2.4.1" },
  { t: "reverse transcriptase", a: [], d: "A viral enzyme that uses viral RNA as a template to make DNA, then double-stranded DNA.", r: "3.2.4.1" },
  { t: "reverse transcription", a: [], d: "Making DNA from an RNA template, the reverse of transcription; catalysed by reverse transcriptase.", r: "3.2.4.2" },
  { t: "integrase", a: [], d: "A viral enzyme that inserts the double-stranded viral DNA into a chromosome of the host cell.", r: "3.2.4.1" },
  { t: "protease", a: [], d: "An enzyme that hydrolyses peptide bonds. HIV protease cuts long viral protein chains into functional proteins after budding, so new particles mature and become infectious.", r: "3.2.4.1" },
  { t: "budding", a: [], d: "The release of new virus particles through the host cell's plasma membrane, which wraps each one in an envelope.", r: "3.2.4.1" },
  { t: "CD4 receptor", a: ["CD4"], d: "A glycoprotein on the surface of helper T cells; HIV attaches by binding its envelope glycoprotein to this complementary receptor.", r: "3.2.4.2" },
  { t: "helper T cell", a: ["helper T-cell", "T helper cell", "T-helper cell"], d: "A T cell with CD4 receptors that initiates the body's response to infections, e.g. by stimulating B cells to divide; the host cell of HIV.", r: "3.2.4.2" },
  { t: "opportunistic infection", a: [], d: "An infection by a pathogen that rarely harms people with a working immune system but causes disease when the immune system is weakened, as in AIDS.", r: "3.2.4.2" },
  { t: "antiretroviral therapy", a: ["antiretroviral", "antiretroviral drug"], d: "Treatment with drugs that block steps in the HIV replication cycle, e.g. by inhibiting viral enzymes; it suppresses the virus but does not cure the infection.", r: "3.2.4.2" },

  // 3.2.5.1 Principles of immunology
  { t: "antigen", a: [], d: "A molecule, often a protein on a cell surface, that is recognised as non-self and triggers an immune response, including the production of antibodies.", r: "3.2.5.1" },
  { t: "non-self", a: [], d: "Describes molecules that are not the body's own, e.g. on pathogens, toxins, cells from other people and abnormal body cells; they act as antigens.", r: "3.2.5.1" },
  { t: "antigen variability", a: ["antigenic variability"], d: "Changes in the shape of a pathogen's antigens caused by mutation, so existing antibodies and memory cells are no longer complementary; people can be reinfected and vaccines must be updated.", r: "3.2.5.1" },
  { t: "immune response", a: [], d: "The body's response to a pathogen or other non-self material: non-specific defences such as phagocytosis, and the specific response carried out by lymphocytes (T cells and B cells).", r: "3.2.5.1" },
  { t: "lymphocyte", a: [], d: "A type of white blood cell responsible for the specific immune response: B cells and T cells.", r: "3.2.5.1" },
  { t: "T cell", a: ["T lymphocyte", "T-cell"], d: "A lymphocyte that matures in the thymus and is involved in cell-mediated immunity, responding to antigens displayed on the surface of cells.", r: "3.2.5.1" },
  { t: "B cell", a: ["B lymphocyte", "B-cell"], d: "A lymphocyte primarily responsible for humoral immunity: when stimulated it divides, forming plasma cells that release antibodies and memory cells.", r: "3.2.5.1" },
  { t: "cell-mediated immunity", a: ["cell-mediated response", "cell-mediated"], d: "The immune response carried out by T cells, which respond to antigens on the surface of cells.", r: "3.2.5.1" },
  { t: "humoral immunity", a: ["humoral response", "humoral"], d: "The immune response, mainly by B cells, that involves the production and release of antibodies into the body fluids.", r: "3.2.5.1" },
  { t: "cytotoxic T cell", a: ["cytotoxic T-cell", "killer T cell"], d: "A T cell that destroys body cells displaying a complementary antigen, such as virus-infected cells.", r: "3.2.5.1" },
  { t: "phagocyte", a: [], d: "A white blood cell that engulfs and digests pathogens by phagocytosis, e.g. neutrophils and macrophages.", r: "3.2.5.1" },
  { t: "phagocytosis", a: [], d: "The engulfing of a pathogen by a phagocyte into a phagosome, which fuses with lysosomes whose hydrolytic enzymes digest the pathogen.", r: "3.2.5.1" },
  { t: "phagosome", a: [], d: "The vesicle, formed from the cell-surface membrane, that encloses a pathogen engulfed by a phagocyte.", r: "3.2.5.1" },
  { t: "pseudopodium", a: ["pseudopodia"], d: "An extension of the cytoplasm and cell-surface membrane of a phagocyte that flows around a pathogen to engulf it.", r: "3.2.5.1" },
  { t: "macrophage", a: [], d: "A large phagocyte found in tissues; after phagocytosis it displays the pathogen's antigens and acts as an antigen-presenting cell.", r: "3.2.5.1" },
  { t: "neutrophil", a: [], d: "A phagocyte with a lobed nucleus; usually the first white blood cell to reach a site of infection.", r: "3.2.5.1" },

  // 3.2.5.2 B cells and antibodies
  { t: "antigen-presenting cell", a: ["antigen presenting cell", "APC"], d: "A cell that displays antigens on its cell-surface membrane, e.g. a macrophage after phagocytosis or an infected body cell; helper T cells with complementary receptors bind to it.", r: "3.2.5.2" },
  { t: "antibody", a: ["antibodies", "immunoglobulin"], d: "A protein made by plasma cells that binds specifically to a complementary antigen, forming an antigen-antibody complex. It has four polypeptide chains: two heavy and two light.", r: "3.2.5.2" },
  { t: "heavy chain", a: [], d: "One of the two longer polypeptide chains of an antibody, joined to the other chains by disulfide bridges.", r: "3.2.5.2" },
  { t: "light chain", a: [], d: "One of the two shorter polypeptide chains of an antibody, each joined to a heavy chain by a disulfide bridge.", r: "3.2.5.2" },
  { t: "variable region", a: [], d: "The tip of each arm of an antibody, whose amino acid sequence differs between antibodies; it forms the antigen-binding site.", r: "3.2.5.2" },
  { t: "constant region", a: [], d: "The part of an antibody whose amino acid sequence is the same in all antibodies of one type; it can bind to receptors on phagocytes.", r: "3.2.5.2" },
  { t: "antigen-binding site", a: ["antigen binding site"], d: "The site at the tip of each arm of an antibody, formed by the variable regions, that is complementary to one specific antigen; each antibody has two.", r: "3.2.5.2" },
  { t: "hinge region", a: [], d: "The flexible part of an antibody where the arms join the stem; it lets the arms move to bind two antigens.", r: "3.2.5.2" },
  { t: "antigen-antibody complex", a: ["antigen–antibody complex", "antigen antibody complex"], d: "The structure formed when an antibody binds to its complementary antigen; it leads to destruction of the antigen by agglutination and phagocytosis.", r: "3.2.5.2" },
  { t: "agglutination", a: [], d: "The clumping of bacteria when antibodies, each with two antigen-binding sites, bind antigens on different cells; the clumps are engulfed by phagocytes.", r: "3.2.5.2" },
  { t: "plasma cell", a: [], d: "A short-lived cell formed from a B cell that secretes large amounts of one specific antibody into the blood and lymph.", r: "3.2.5.3" },
  { t: "memory cell", a: [], d: "A long-lived lymphocyte that remains after an infection or vaccination; on re-exposure to the antigen it divides rapidly, giving the secondary immune response.", r: "3.2.5.3" },
  { t: "clonal selection", a: [], d: "The activation of the one B cell (or T cell) with receptors complementary to an antigen, which then divides by mitosis to form a clone of identical cells.", r: "3.2.5.2" },

  // 3.2.5.3 Vaccination
  { t: "vaccine", a: [], d: "A preparation containing antigens (e.g. a dead or weakened pathogen or its isolated antigens), or instructions to make them, that stimulates a primary immune response so memory cells form.", r: "3.2.5.3" },
  { t: "vaccination", a: ["immunisation", "immunization"], d: "Giving a vaccine to stimulate the production of memory cells, so that a later infection meets a rapid secondary response before symptoms develop.", r: "3.2.5.3" },
  { t: "primary immune response", a: ["primary response"], d: "The first response to an antigen: after a lag of several days, plasma cells release antibodies and memory cells form.", r: "3.2.5.3" },
  { t: "secondary immune response", a: ["secondary response"], d: "The response when an antigen is met again: memory cells divide rapidly into plasma cells, so antibodies appear sooner, rise faster and reach much higher levels than in the primary response.", r: "3.2.5.3" },
  { t: "herd immunity", a: ["population immunity"], d: "Indirect protection of people who are not immune when a large enough proportion of the population is immune, so chains of transmission are broken.", r: "3.2.5.3" },
  { t: "active immunity", a: [], d: "Immunity from a person's own immune response: their plasma cells make antibodies and memory cells form. Natural after infection; artificial after vaccination. Long-lasting.", r: "3.2.5.3" },
  { t: "passive immunity", a: [], d: "Immunity from antibodies made by another organism, e.g. across the placenta or by injection; immediate but short-lived, because no memory cells are made.", r: "3.2.5.3" },
  { t: "booster", a: ["booster dose"], d: "A further dose of a vaccine that triggers a secondary response, raising antibody levels and the number of memory cells.", r: "3.2.5.3" },
  { t: "vaccine efficacy", a: ["efficacy"], d: "How well a vaccine prevents disease in a controlled trial: the percentage reduction in the attack rate of vaccinated people compared with the placebo group.", r: "3.2.5.3" },

  // 3.2.6.1 Blood vessels and tissue fluid
  { t: "artery", a: ["arteries"], d: "A blood vessel that carries blood away from the heart at high pressure; it has a thick wall of elastic tissue, smooth muscle and collagen, and a narrow lumen.", r: "3.2.6.1" },
  { t: "arteriole", a: [], d: "A small artery with a mainly muscular wall that constricts or widens to control the blood flow into capillaries.", r: "3.2.6.1" },
  { t: "capillary", a: ["capillaries"], d: "The smallest blood vessel, with a wall one cell thick (endothelium) and a narrow lumen; the site of metabolic exchange between the blood and the cells. (In a potometer, a capillary tube is a narrow glass tube.)", r: "3.2.6.1" },
  { t: "venule", a: [], d: "A small vein that collects blood from capillaries.", r: "3.2.6.1" },
  { t: "vein", a: [], d: "A blood vessel that returns blood to the heart at low pressure; it has a thin wall, a wide lumen and valves to prevent backflow. (In a leaf, a vein is a bundle of xylem and phloem.)", r: "3.2.6.1" },
  { t: "elastic tissue", a: ["elastic fibres", "elastic fibre"], d: "Tissue in artery walls that stretches as blood is pumped in and recoils between beats, smoothing the flow and maintaining the pressure.", r: "3.2.6.1" },
  { t: "smooth muscle", a: [], d: "Involuntary muscle, e.g. in the walls of arteries, arterioles and bronchioles; it contracts or relaxes to narrow or widen the lumen.", r: "3.2.6.1" },
  { t: "collagen", a: [], d: "A tough fibrous protein that gives strength to tissues such as artery walls, so they withstand high pressure.", r: "3.2.6.1" },
  { t: "endothelium", a: ["endothelial"], d: "The single layer of thin, flattened cells that lines all blood vessels; it forms the entire wall of a capillary.", r: "3.2.6.1" },
  { t: "lumen", a: [], d: "The space inside a tube-like structure, such as a blood vessel or the gut.", r: "3.2.6.1" },
  { t: "valve", a: [], d: "A flap of tissue that closes to prevent backflow, so blood flows in one direction only, e.g. in veins and in the heart.", r: "3.2.6.1" },
  { t: "metabolic exchange", a: [], d: "The exchange of substances, such as oxygen, glucose and carbon dioxide, between the blood and the cells of tissues, through capillary walls.", r: "3.2.6.1" },
  { t: "tissue fluid", a: [], d: "The fluid that bathes the cells of tissues, formed from blood plasma forced out of capillaries; it contains water, glucose, amino acids, ions and oxygen but no red cells and very little protein.", r: "3.2.6.1" },
  { t: "plasma protein", a: [], d: "A protein dissolved in blood plasma, such as albumin; too large to leave capillaries, so it lowers the water potential of the blood.", r: "3.2.6.1" },
  { t: "hydrostatic pressure", a: [], d: "The pressure exerted by a liquid. In a capillary, the blood pressure produced by the heart, which pushes fluid out; in phloem, the pressure that drives mass flow.", r: "3.2.6.1" },
  { t: "oncotic pressure", a: [], d: "The effect of plasma proteins, which lower the water potential of the blood and so tend to draw water back into the capillary by osmosis.", r: "3.2.6.1" },
  { t: "ultrafiltration", a: [], d: "Filtration under pressure: blood pressure forces water and small solutes out through the gaps in capillary walls, leaving cells and large proteins behind.", r: "3.2.6.1" },
  { t: "lymph", a: [], d: "Excess tissue fluid that drains into lymph capillaries and is carried in lymph vessels back to the blood in veins near the heart.", r: "3.2.6.1" },
  { t: "lymphatic system", a: ["lymphatic"], d: "The network of lymph capillaries and vessels that returns excess tissue fluid to the blood.", r: "3.2.6.1" },
  { t: "lymph capillary", a: ["lymph capillaries", "lymph vessel", "lymphatic vessel"], d: "A blind-ended vessel of the lymphatic system that collects excess tissue fluid, which is then called lymph.", r: "3.2.6.1" },
  { t: "oedema", a: [], d: "Swelling caused by tissue fluid building up in the tissues, e.g. when venous pressure is raised or plasma protein is low.", r: "3.2.6.1" },

  // 3.2.6.2 The heart
  { t: "atrium", a: ["atria"], d: "One of the two thin-walled upper chambers of the heart, which receive blood from the veins and pump it into the ventricles.", r: "3.2.6.2" },
  { t: "ventricle", a: [], d: "One of the two lower chambers of the heart, with thick muscular walls, which pump blood into the arteries; the left ventricle wall is the thickest.", r: "3.2.6.2" },
  { t: "septum", a: [], d: "A dividing wall. In the heart, the wall between the left and right sides that keeps oxygenated and deoxygenated blood apart. In binary fission, the wall that grows across a dividing cell.", r: "3.2.6.2" },
  { t: "atrioventricular valve", a: ["AV valve", "tricuspid valve", "bicuspid valve", "mitral valve"], d: "A valve between an atrium and a ventricle (tricuspid on the right, bicuspid on the left) that prevents backflow into the atrium when the ventricle contracts.", r: "3.2.6.2" },
  { t: "semilunar valve", a: ["SL valve", "aortic valve", "pulmonary valve"], d: "A valve at the base of the aorta or the pulmonary artery that prevents backflow into the ventricle when it relaxes.", r: "3.2.6.2" },
  { t: "chordae tendineae", a: [], d: "Tendons joining the flaps of the atrioventricular valves to the ventricle wall; they stop the valves turning inside out when the ventricles contract.", r: "3.2.6.2" },
  { t: "cardiac muscle", a: ["heart muscle"], d: "The muscle of the heart wall, which contracts rhythmically without tiring; it needs a constant supply of oxygen from the coronary arteries for aerobic respiration.", r: "3.2.6.2" },
  { t: "cardiac cycle", a: [], d: "The sequence of contraction (systole) and relaxation (diastole) of the heart chambers in one heartbeat, with the associated pressure, volume and valve changes.", r: "3.2.6.2" },
  { t: "systole", a: [], d: "The contraction phase of the cardiac cycle.", r: "3.2.6.2" },
  { t: "diastole", a: [], d: "The relaxation phase of the cardiac cycle, when the heart chambers fill with blood.", r: "3.2.6.2" },
  { t: "atrial systole", a: [], d: "Contraction of the atria, pushing the last of the blood through the open atrioventricular valves into the relaxed ventricles.", r: "3.2.6.2" },
  { t: "ventricular systole", a: [], d: "Contraction of the ventricles: pressure rises, closing the atrioventricular valves, then opening the semilunar valves so blood is ejected into the arteries.", r: "3.2.6.2" },
  { t: "stroke volume", a: [], d: "The volume of blood pumped out of one ventricle in one heartbeat: end-diastolic volume minus end-systolic volume.", r: "3.2.6.2" },
  { t: "heart rate", a: [], d: "The number of heartbeats per minute.", r: "3.2.6.2" },
  { t: "cardiac output", a: [], d: "The volume of blood pumped by one ventricle per minute: cardiac output = heart rate × stroke volume.", r: "3.2.6.2" },

  // 3.2.7 Heart disease
  { t: "atheroma", a: [], d: "The presence of lipid-containing material within the walls of the arteries, beneath the endothelium; it narrows the lumen and increases the risk of thrombosis and aneurysm.", r: "3.2.7.1" },
  { t: "plaque", a: ["atheromatous plaque"], d: "The swelling formed by atheroma in an artery wall: a lipid core with fibrous tissue and white blood cells, which bulges into the lumen.", r: "3.2.7.1" },
  { t: "atherosclerosis", a: [], d: "Hardening and narrowing of arteries caused by the build-up of atheroma.", r: "3.2.7.1" },
  { t: "thrombosis", a: [], d: "The formation of a blood clot (thrombus) inside a blood vessel, e.g. where the endothelium over an atheroma is damaged.", r: "3.2.7.1" },
  { t: "thrombus", a: ["thrombi"], d: "A blood clot formed inside a blood vessel.", r: "3.2.7.1" },
  { t: "platelet", a: [], d: "A small cell fragment in the blood that sticks to damaged vessel walls and starts the formation of a blood clot.", r: "3.2.7.1" },
  { t: "embolus", a: ["emboli"], d: "A piece of thrombus or plaque that breaks off, is carried in the blood and blocks a smaller artery further along.", r: "3.2.7.1" },
  { t: "aneurysm", a: [], d: "A balloon-like swelling of a weakened artery wall, filled with blood; it may burst, causing a haemorrhage.", r: "3.2.7.1" },
  { t: "haemorrhage", a: [], d: "Severe bleeding from a burst blood vessel.", r: "3.2.7.1" },
  { t: "myocardial infarction", a: ["heart attack"], d: "Damage or death of part of the heart muscle caused by an interruption of its blood flow, usually a thrombus blocking a coronary artery, so the cells lack oxygen for aerobic respiration.", r: "3.2.7.1" },
  { t: "angina", a: [], d: "Chest pain, often during exercise, caused by reduced blood flow to the heart muscle through narrowed coronary arteries.", r: "3.2.7.1" },
  { t: "LDL", a: ["low-density lipoprotein"], d: "Low-density lipoprotein: carries cholesterol in the blood to cells; high LDL levels are associated with more atheroma and a higher risk of coronary heart disease.", r: "3.2.7.2" },
  { t: "HDL", a: ["high-density lipoprotein"], d: "High-density lipoprotein: carries cholesterol in the blood to the liver; higher HDL levels are associated with a lower risk of coronary heart disease.", r: "3.2.7.2" },
  { t: "high blood pressure", a: ["hypertension"], d: "Blood pressure that is persistently higher than normal; it damages the endothelium of arteries and is a risk factor for coronary heart disease and aneurysm.", r: "3.2.7.2" },

  // 3.2.8.1 Xylem and water transport
  { t: "xylem", a: [], d: "Plant tissue that transports water and mineral ions from the roots up to the leaves, mainly in xylem vessels.", r: "3.2.8.1" },
  { t: "xylem vessel", a: [], d: "A long, continuous tube of dead cells with no end walls and walls thickened with lignin; pits in the walls let water move sideways.", r: "3.2.8.1" },
  { t: "phloem", a: [], d: "Plant tissue that transports organic substances, mainly sucrose and amino acids, from sources to sinks in sieve tubes.", r: "3.2.8.2" },
  { t: "root hair", a: ["root hair cell"], d: "A long, thin extension of a root epidermal cell, giving a large surface area for taking up water by osmosis and mineral ions by active transport.", r: "3.2.8.1" },
  { t: "epidermis", a: [], d: "The outer layer of cells of a plant organ such as a leaf or a root.", r: "3.2.8.1" },
  { t: "cortex", a: [], d: "The wide layer of large, thin-walled cells between the epidermis and the endodermis of a root, across which water passes to the xylem.", r: "3.2.8.1" },
  { t: "endodermis", a: [], d: "The ring of cells around the central xylem and phloem of a root; their Casparian strip forces water and ions into the symplastic pathway.", r: "3.2.8.1" },
  { t: "pericycle", a: [], d: "The layer of cells just inside the endodermis of a root, around the xylem and phloem.", r: "3.2.8.1" },
  { t: "apoplastic pathway", a: ["apoplast", "apoplastic", "apoplast pathway"], d: "The route by which water moves through the cell walls and the spaces between cells, without crossing any membranes.", r: "3.2.8.1" },
  { t: "symplastic pathway", a: ["symplast", "symplastic", "symplast pathway"], d: "The route by which water moves from cell to cell through the cytoplasm and plasmodesmata, entering the first cell across its cell-surface membrane by osmosis.", r: "3.2.8.1" },
  { t: "vacuolar pathway", a: [], d: "A route in which water moves through the cytoplasm and the vacuoles of cells, crossing their membranes by osmosis.", r: "3.2.8.1" },
  { t: "plasmodesma", a: ["plasmodesmata"], d: "A narrow strand of cytoplasm through a gap in plant cell walls that links the cytoplasm of neighbouring cells.", r: "3.2.8.1" },
  { t: "Casparian strip", a: [], d: "A waterproof band in the walls of endodermis cells that blocks the apoplastic pathway, so water and mineral ions must cross a cell-surface membrane to reach the xylem.", r: "3.2.8.1" },
  { t: "lignin", a: [], d: "A strong, waterproof polymer that thickens the walls of xylem vessels, so they do not collapse under tension.", r: "3.2.8.1" },
  { t: "root pressure", a: [], d: "Pressure in the xylem of the root, caused by active transport of mineral ions into the xylem, which lowers its water potential so water enters by osmosis and is pushed up.", r: "3.2.8.1" },
  { t: "guttation", a: [], d: "The loss of drops of liquid water from the edges of leaves, caused by root pressure.", r: "3.2.8.1" },
  { t: "transpiration", a: [], d: "The loss of water vapour from the aerial parts of a plant, mainly through the stomata: water evaporates from mesophyll cell walls and diffuses out. Light, temperature, humidity and air movement affect its rate.", r: "3.2.8.1" },
  { t: "transpiration stream", a: [], d: "The continuous movement of water from the roots, up the xylem, to the leaves, where it is lost by transpiration.", r: "3.2.8.1" },
  { t: "cohesion-tension theory", a: ["cohesion–tension theory", "cohesion-tension", "cohesion–tension"], d: "The explanation of how water rises in xylem: transpiration puts the water column under tension, and cohesion holds the column together so water is pulled up.", r: "3.2.8.1" },
  { t: "cohesion", a: [], d: "The attraction between water molecules caused by hydrogen bonds, which holds the water in the xylem together as a continuous column.", r: "3.2.8.1" },
  { t: "adhesion", a: [], d: "The attraction between molecules of different substances: in the xylem, between water molecules and the walls of the vessels. (Cell adhesion, aided by membrane glycoproteins, is cells sticking together.)", r: "3.2.8.1" },
  { t: "tension", a: [], d: "A pulling force. In the xylem, the negative pressure created as water is lost by transpiration, which pulls the water column upwards.", r: "3.2.8.1" },
  { t: "capillary tube", a: [], d: "A narrow glass tube; in a potometer, the rate of water uptake is found from how far the meniscus or an air bubble moves along it in a set time.", r: "3.2.8.1" },
  { t: "potometer", a: [], d: "Apparatus that measures the rate of water uptake by a cut shoot, which is close to (but not the same as) its rate of transpiration.", r: "3.2.8.1" },

  // 3.2.8.2 Phloem and translocation
  { t: "translocation", a: [], d: "The movement of organic substances, mainly sucrose and amino acids, in the phloem from sources to sinks.", r: "3.2.8.2" },
  { t: "source", a: [], d: "In plant transport, a part of a plant that loads sugars into the phloem, e.g. a photosynthesising leaf or a storage organ releasing its reserves. (Elsewhere the word has its everyday meaning.)", r: "3.2.8.2" },
  { t: "sink", a: [], d: "A part of a plant that removes sugars from the phloem to use or store them, e.g. root tips, growing leaves, fruits and filling storage organs.", r: "3.2.8.2" },
  { t: "mass flow hypothesis", a: ["mass flow", "mass-flow hypothesis", "mass flow theory", "pressure flow hypothesis"], d: "The explanation of translocation: sucrose loaded at a source lowers the water potential, water enters by osmosis and raises the hydrostatic pressure, and sap flows along the sieve tubes towards the lower pressure at a sink.", r: "3.2.8.2" },
  { t: "sieve tube element", a: ["sieve tube", "sieve element", "sieve tube member"], d: "A living cell of the phloem with no nucleus and little cytoplasm, joined end to end with others through sieve plates to form a sieve tube.", r: "3.2.8.2" },
  { t: "sieve plate", a: [], d: "The perforated end wall between two sieve tube elements, through which phloem sap flows.", r: "3.2.8.2" },
  { t: "companion cell", a: [], d: "A cell beside each sieve tube element, with a nucleus and many mitochondria, that supplies ATP for the active loading of sucrose.", r: "3.2.8.2" },
  { t: "phloem sap", a: [], d: "The solution transported in sieve tubes, mainly sucrose and amino acids in water, under high hydrostatic pressure.", r: "3.2.8.2" },
  { t: "proton pump", a: [], d: "A carrier protein that uses ATP to pump hydrogen ions out of a cell; their diffusion back in through a co-transporter carries sucrose into companion cells.", r: "3.2.8.2" },
  { t: "ringing", a: ["ringing experiment", "girdling"], d: "Removing a ring of bark, including the phloem, from a stem; sugars build up above the ring, which is evidence that phloem transports organic substances.", r: "3.2.8.2" },
  { t: "radioactive tracer", a: [], d: "A radioactive isotope, e.g. ¹⁴C in carbon dioxide, built into molecules so their movement can be followed.", r: "3.2.8.2" },
  { t: "autoradiography", a: ["autoradiograph"], d: "Placing a section of tissue on photographic film, which darkens where radioactive substances are present, e.g. showing ¹⁴C-labelled sugars only in the phloem.", r: "3.2.8.2" },

  // 3.2.9 Aphids and plant viruses
  { t: "vector", a: [], d: "An organism that carries a pathogen from one host to another, e.g. aphids carrying plant viruses. (In genetic engineering, a vector is a carrier, such as a plasmid, that transfers DNA into a cell.)", r: "3.2.9.1" },
  { t: "aphid", a: [], d: "A small insect that feeds on phloem sap by inserting its stylets into sieve tubes; an important vector of plant viruses.", r: "3.2.9.2" },
  { t: "stylet", a: [], d: "One of the long, fine needle-like sucking mouthparts of an aphid, pushed into a plant to reach the phloem.", r: "3.2.9.2" },
  { t: "honeydew", a: [], d: "The sugary liquid that passes out of an aphid's gut, because aphids take in far more sugar than they need.", r: "3.2.9.2" },

  // 3.2.10 Cell division
  { t: "cell cycle", a: [], d: "The sequence of events in a eukaryotic cell that can divide: interphase (G1, S and G2), then mitosis and cytokinesis.", r: "3.2.10.1" },
  { t: "interphase", a: [], d: "The period between mitotic divisions, divided into the G1 phase, S phase and G2 phase; the cell grows, makes proteins and organelles and replicates its DNA. It is not a resting phase.", r: "3.2.10.1" },
  { t: "G1 phase", a: ["G₁ phase"], d: "The first phase of interphase: the cell increases its protein content and the number of organelles such as mitochondria and ribosomes, and grows in size.", r: "3.2.10.1" },
  { t: "S phase", a: ["S-phase", "synthesis phase"], d: "The phase of interphase in which DNA is replicated, so each chromosome comes to consist of two sister chromatids.", r: "3.2.10.1" },
  { t: "G2 phase", a: ["G₂ phase"], d: "The last phase of interphase, with rapid cell growth and protein synthesis, before mitosis.", r: "3.2.10.1" },
  { t: "chromatin", a: [], d: "DNA with its associated proteins, uncoiled as long thin threads in the nucleus during interphase.", r: "3.2.10.1" },
  { t: "meristem", a: [], d: "A region of a plant, e.g. a root tip or shoot tip, where cells keep the ability to divide by mitosis.", r: "3.2.10.1" },
  { t: "mitosis", a: ["mitotic division"], d: "Division of the nucleus of a eukaryotic cell into two genetically identical nuclei with the same number of chromosomes as the parent; stages: prophase, metaphase, anaphase, telophase. Cytokinesis then divides the cytoplasm.", r: "3.2.10.2" },
  { t: "cytokinesis", a: [], d: "The division of the cytoplasm after mitosis, producing two separate daughter cells.", r: "3.2.10.2" },
  { t: "prophase", a: [], d: "The first stage of nuclear division (mitosis, or each division of meiosis): chromosomes condense and become visible as two sister chromatids, the spindle forms, the nucleolus disappears and the nuclear envelope breaks down. (In prophase I, homologous chromosomes also pair up.)", r: "3.2.10.2" },
  { t: "metaphase", a: [], d: "The stage of nuclear division in which chromosomes line up on the equator, attached by their centromeres to spindle fibres. In mitosis (and meiosis II) they line up singly; in metaphase I of meiosis, homologous pairs line up.", r: "3.2.10.2" },
  { t: "anaphase", a: [], d: "The stage of nuclear division in which spindle fibres shorten and pull material to opposite poles: in mitosis (and meiosis II) the centromeres divide and sister chromatids separate, centromere first; in anaphase I of meiosis, whole homologous chromosomes separate.", r: "3.2.10.2" },
  { t: "telophase", a: [], d: "The last stage of nuclear division: chromosomes reach the poles and uncoil, nuclear envelopes re-form, nucleoli reappear and the spindle breaks down.", r: "3.2.10.2" },
  { t: "spindle", a: ["spindle fibre", "spindle fiber"], d: "A structure of protein fibres that forms during nuclear division; spindle fibres attach to the centromeres and shorten to pull chromatids (or chromosomes) to opposite poles.", r: "3.2.10.2" },
  { t: "centromere", a: [], d: "The region where the two sister chromatids of a chromosome are joined, and where spindle fibres attach.", r: "3.2.10.2" },
  { t: "equator", a: [], d: "The plane across the middle of a dividing cell, midway between the poles of the spindle, where the chromosomes line up.", r: "3.2.10.2" },
  { t: "mitotic index", a: [], d: "The proportion of cells in a sample that are in a stage of mitosis: number of cells in mitosis ÷ total number of cells.", r: "3.2.10.2" },
  { t: "binary fission", a: [], d: "Division of a prokaryotic cell: the circular DNA and plasmids replicate, then the cytoplasm divides to produce two daughter cells, each with one copy of the circular DNA and a variable number of plasmids.", r: "3.2.10.3" },
  { t: "generation time", a: [], d: "The time taken for a population of bacteria to double in number by binary fission.", r: "3.2.10.3" },
  { t: "conjugation", a: [], d: "The passing of DNA, often a plasmid, from one bacterium to another, even of a different species, through a pilus or direct contact; an example of horizontal gene transmission.", r: "3.2.10.3" },
  { t: "pilus", a: ["pili"], d: "A thin protein tube on the surface of a bacterium that attaches to another cell and draws the two together during conjugation.", r: "3.2.10.3" },
  { t: "horizontal gene transmission", a: ["horizontal gene transfer"], d: "The passing of genes between existing cells, even of different species, rather than from a parent cell to its daughter cells; e.g. by conjugation.", r: "3.2.10.3" },
  { t: "vertical gene transmission", a: ["vertical gene transfer"], d: "The passing of genes from a parent cell to its daughter cells, e.g. by binary fission.", r: "3.2.10.3" },
  { t: "antibiotic resistance", a: [], d: "The ability of a bacterium to survive an antibiotic, usually because of an allele or gene, often carried on a plasmid, that can spread by conjugation.", r: "3.2.10.3" },

  // 3.2.11 Mutation and cancer
  { t: "gene mutation", a: ["mutation"], d: "A change in the base sequence of DNA. Gene mutations arise spontaneously during DNA replication, and mutagens increase their frequency.", r: "3.2.11.1" },
  { t: "mutagen", a: [], d: "A physical or chemical agent that increases the frequency of mutations, e.g. ionising radiation, ultraviolet light and some chemicals in tobacco smoke.", r: "3.2.11.1" },
  { t: "carcinogen", a: [], d: "An agent that causes cancer or increases its risk; most carcinogens are mutagens, e.g. ionising radiation, ultraviolet light and chemicals in tobacco smoke.", r: "3.2.11.1" },
  { t: "ionising radiation", a: ["ionizing radiation"], d: "High-energy radiation, such as X-rays and gamma rays, that can damage DNA; a physical mutagen.", r: "3.2.11.1" },
  { t: "base substitution", a: ["substitution"], d: "A gene mutation in which one base is replaced by a different base; only one codon changes, so at most one amino acid changes.", r: "3.2.11.1" },
  { t: "base deletion", a: ["deletion"], d: "A gene mutation in which a base is lost. Unless bases are lost in a multiple of three, it shifts the reading frame, so the codons after it change.", r: "3.2.11.1" },
  { t: "base insertion", a: ["insertion"], d: "A gene mutation in which an extra base is added. Unless bases are added in a multiple of three, it shifts the reading frame, like a deletion.", r: "3.2.11.1" },
  { t: "frameshift", a: ["frameshift mutation", "frame shift"], d: "A change in the reading frame caused by deleting or inserting bases (not in a multiple of three), which changes every codon after it.", r: "3.2.11.1" },
  { t: "silent mutation", a: [], d: "A base substitution that does not change the amino acid coded for, because the genetic code is degenerate.", r: "3.2.11.1" },
  { t: "missense mutation", a: ["missense"], d: "A base substitution that changes one amino acid in the polypeptide.", r: "3.2.11.1" },
  { t: "nonsense mutation", a: [], d: "A base substitution that creates a stop codon, so a shorter polypeptide is made.", r: "3.2.11.1" },
  { t: "tumour", a: [], d: "A mass of cells formed when cells divide by mitosis without the normal control.", r: "3.2.11.2" },
  { t: "benign tumour", a: ["benign"], d: "A tumour that grows slowly, is usually enclosed in a capsule, does not invade nearby tissue and does not spread; it can still harm by pressing on organs.", r: "3.2.11.2" },
  { t: "malignant tumour", a: ["malignant"], d: "A cancerous tumour that grows faster, has no capsule, invades nearby tissues and can spread to form secondary tumours (metastasis).", r: "3.2.11.2" },
  { t: "metastasis", a: ["metastases", "metastasise"], d: "The spread of cells from a malignant tumour in the blood or lymph to form secondary tumours elsewhere in the body.", r: "3.2.11.2" },
  { t: "secondary tumour", a: [], d: "A tumour formed in a new part of the body by cells that have spread from a malignant tumour.", r: "3.2.11.2" },
  { t: "proto-oncogene", a: [], d: "A normal gene coding for a protein that stimulates cell division, e.g. a growth factor receptor.", r: "3.2.11.2" },
  { t: "oncogene", a: [], d: "A mutated proto-oncogene that stimulates cells to divide too quickly, e.g. because its protein is permanently activated.", r: "3.2.11.2" },
  { t: "tumour suppressor gene", a: [], d: "A gene coding for a protein that slows cell division, e.g. by stopping the cell cycle if DNA is damaged; when mutated it is inactivated, so the rate of cell division increases.", r: "3.2.11.2" },
  { t: "growth factor", a: [], d: "A signalling molecule that binds to a receptor on a cell and stimulates it to divide.", r: "3.2.11.2" },
] };
